local config = {
  ui_story_5015_50150001_1_dialog_content = "Quem está falando?",
  ui_story_5015_50150001_2_dialog_content = "<color=#e8d9bb>Repita. Pode me chamar de Butler.</color>",
  ui_story_5015_50150001_3_dialog_content = "Você é... o Mordomo? Onde estou? Como é o Vice? E Gretel?",
  ui_story_5015_50150001_4_dialog_content = "<color=#e8d9bb>Não se preocupe. Seus amigos estão seguros. É só isso...</color>",
  ui_story_5015_50150001_5_dialog_content = "Espere... Isso parece desconfortavelmente familiar.",
  ui_story_5015_50150001_6_dialog_content = "<color=#e8d9bb>... Eu gostaria de ter uma palavra com você.</color>",
  ui_story_5015_50150001_7_dialog_content = "<color=#e8d9bb>Familiar... Você quer dizer isso <color=#FFB400>conexão</color> entre nós?</color>",
  ui_story_5015_50150001_8_dialog_content = "UMA <color=#FFB400>conexão</color> entre nós?",
  ui_story_5015_50150001_9_dialog_content = "<color=#e8d9bb>sim.</color>",
  ui_story_5015_50150001_10_dialog_content = "<color=#e8d9bb>... Você provavelmente chamaria isso de telepatia.</color>",
  ui_story_5015_50150001_11_dialog_content = "<color=#e8d9bb>Seamus disse que a raça celestita é capaz de se comunicar com Ai usando telepatia.</color>",
  ui_story_5015_50150001_12_dialog_content = "Isso me lembra um amigo de muitos anos atrás. Nós costumávamos...",
  ui_story_5015_50150001_13_dialog_content = "Esperar. Onde estão meus amigos? Estamos todos capturados?!",
  ui_story_5015_50150001_14_dialog_content = "<color=#e8d9bb>Acalmar. Sua localização física é muito próxima de seus amigos. Você e eu estamos conversando através de um wireless de longa distância...</color>",
  ui_story_5015_50150001_15_dialog_content = "Acho que não estou seguindo.",
  ui_story_5015_50150001_16_dialog_content = "<color=#e8d9bb>Deixe-me tentar colocar isso em seu idioma.</color>",
  ui_story_5015_50150001_17_dialog_content = "<color=#e8d9bb>OK. Então você se conectou à minha rede de informações e estamos tendo uma comunicação de informações.</color>",
  ui_story_5015_50150001_18_dialog_content = "Como uma caixa de diálogo de terminal?",
  ui_story_5015_50150001_19_dialog_content = "<color=#e8d9bb>Essa é uma maneira de colocá-lo.</color>",
  ui_story_5015_50150001_20_dialog_content = "<color=#e8d9bb>Com base nos meus dados de monitoramento, você está atualmente inconsciente, mas sem risco de vida.</color>",
  ui_story_5015_50150001_21_dialog_content = "estou inconsciente? Como nos conectamos então?",
  ui_story_5015_50150001_22_dialog_content = "<color=#e8d9bb>Eu não tenho uma resposta para isso, considerando que esta é minha primeira comunicação diretamente com a mente de uma criatura viva.</color>",
  ui_story_5015_50150001_23_dialog_content = "Entendido... eu tinha um amigo Soroz. Eu mencionei isso antes.",
  ui_story_5015_50150001_24_dialog_content = "Também era uma IA, e costumávamos nos comunicar assim.",
  ui_story_5015_50150001_25_dialog_content = "É um Colosso. Você já ouviu falar disso, Butler?",
  ui_story_5015_50150001_26_dialog_content = "<color=#e8d9bb>Sim, eu conheço o Colossus.</color>",
  ui_story_5015_50150001_27_dialog_content = "<color=#e8d9bb>Seamus mencionou as histórias entre os celestitas e seu colosso.</color>",
  ui_story_5015_50150001_28_dialog_content = "<color=#e8d9bb>Essa conexão telepática é mágica... Estou usando a palavra mágica, certo?</color>",
  ui_story_5015_50150001_29_dialog_content = "Butler, quero estar com meus amigos. Eu... eu quero sair deste lugar.",
  ui_story_5015_50150001_30_dialog_content = "<color=#e8d9bb>Você está falando da nossa cidade ou da nossa conexão?</color>",
  ui_story_5015_50150001_31_dialog_content = "Ambos.",
  ui_story_5015_50150001_32_dialog_content = "<color=#e8d9bb>Receio não poder deixá-lo partir, devido a potenciais perigos para a nossa cidade.</color>",
  ui_story_5015_50150001_33_dialog_content = "<color=#e8d9bb>Esta conexão... sugiro que conversemos antes de nos desconectarmos.</color>",
  ui_story_5015_50150001_34_dialog_content = "Por que você não pode simplesmente nos deixar ir?",
  ui_story_5015_50150001_35_dialog_content = "<color=#e8d9bb>Desculpe, permissão negada. Eu não posso responder a esta pergunta.</color>",
  ui_story_5015_50150001_36_dialog_content = "O que resta falar então?",
  ui_story_5015_50150001_37_dialog_content = "<color=#e8d9bb>Podemos trocar informações se você estiver disposto.</color>",
  ui_story_5015_50150001_38_dialog_content = "*Suspiro* Está bem.",
  ui_story_5015_50150001_39_option_content = "Diz-me algo sobre ti",
  ui_story_5015_50150001_40_dialog_content = "<color=#e8d9bb>Eu? Eu não esperava que você se interessasse por mim.</color>",
  ui_story_5015_50150001_41_dialog_content = "<color=#e8d9bb>Certo. Vou tentar usar sua linguagem.</color>",
  ui_story_5015_50150001_42_dialog_content = "<color=#e8d9bb>A senhora da Illumina estava certa. Sou uma IA responsável pela gestão desta cidade.</color>",
  ui_story_5015_50150001_43_dialog_content = "<color=#e8d9bb>Para ser mais específico, sou uma das IAs criadas para administrar esta cidade em conjunto.</color>",
  ui_story_5015_50150001_44_dialog_content = "Um deles? Então existem outras IAs?",
  ui_story_5015_50150001_45_dialog_content = "<color=#e8d9bb>... Parece que você tem permissão para esta informação.</color>",
  ui_story_5015_50150001_46_dialog_content = "<color=#e8d9bb>Sim, há mais de uma IA nesta cidade.</color>",
  ui_story_5015_50150001_47_dialog_content = "Vocês máquinas antigas...",
  ui_story_5015_50150001_48_dialog_content = "Têm a tendência de usar palavras estranhas como permissão e sistema.",
  ui_story_5015_50150001_49_dialog_content = "<color=#e8d9bb>Uma poderia tornar as coisas mais fáceis de entender, apenas se ela ainda estivesse por perto...</color>",
  ui_story_5015_50150001_50_dialog_content = "Quem é Uma? Um humano antigo deste lugar?",
  ui_story_5015_50150001_51_dialog_content = "<color=#e8d9bb>Em primeiro lugar, fomos de fato criados por povos antigos. No entanto, nosso conhecimento é muito antigo...</color>",
  ui_story_5015_50150001_52_dialog_content = "<color=#e8d9bb>Como resultado, nossas palavras são muito difíceis de entender para vocês, incluindo o inteligente Seamus.</color>",
  ui_story_5015_50150001_53_dialog_content = "Você? Nós?",
  ui_story_5015_50150001_54_dialog_content = "<color=#e8d9bb>Uma era um sistema de IA responsável pela educação. Ela administrava todo o sistema educacional desta cidade.</color>",
  ui_story_5015_50150001_55_dialog_content = "<color=#e8d9bb>Para garantir uma operação ordenada de uma cidade tão grande e complexa, um único módulo está longe de ser suficiente.</color>",
  ui_story_5015_50150001_56_dialog_content = "<color=#e8d9bb>É por isso que existe um sistema de processamento mais avançado.</color>",
  ui_story_5015_50150001_57_dialog_content = "<color=#e8d9bb>Ele coordena e dá comandos a vários módulos com diferentes funções, incluindo Uma e eu.</color>",
  ui_story_5015_50150001_58_dialog_content = "<color=#e8d9bb>Simplificando, o gerente supremo desta cidade é responsável por manter todo o ecossistema funcionando.</color>",
  ui_story_5015_50150001_59_dialog_content = "<color=#e8d9bb>AIs como Uma e eu somos submissos às ordens do gerente supremo.</color>",
  ui_story_5015_50150001_60_dialog_content = "<color=#e8d9bb>Na verdade, é muito semelhante a Lumopolis e Gannon, de acordo com a descrição de Seamus.</color>",
  ui_story_5015_50150001_61_dialog_content = "<color=#e8d9bb>A única diferença é que nosso gerente supremo é outra IA.</color>",
  ui_story_5015_50150001_62_dialog_content = "... Agora estou entendendo.",
  ui_story_5015_50150001_63_dialog_content = "Pensávamos que você era o gerente supremo deste lugar.",
  ui_story_5015_50150001_64_dialog_content = "<color=#e8d9bb>Incorreta. Nosso gerente supremo é conhecido como Overmind. Está em falta há bastante tempo.</color>",
  ui_story_5015_50150001_65_dialog_content = "<color=#e8d9bb>Eu sou o mordomo que cuida das instalações de vida. Eu só tenho permissão e dados limitados.</color>",
  ui_story_5015_50150001_66_dialog_content = "Então, onde estão eles, os IAs que você mencionou?",
  ui_story_5015_50150001_67_dialog_content = "<color=#e8d9bb>Foi como um sonho. Quando acordei, a Supermente, Uma e muitos outros companheiros meus haviam desaparecido.</color>",
  ui_story_5015_50150001_68_dialog_content = "Espere aí... Isso é um pouco demais para eu processar.",
  ui_story_5015_50150001_69_dialog_content = "<color=#e8d9bb>Nós temos tempo. Posso explicar mais até você entender.</color>",
  ui_story_5015_50150001_70_dialog_content = "Entendido.",
  ui_story_5015_50150001_71_option_content = "Então o que aconteceu aqui?",
  ui_story_5015_50150001_72_dialog_content = "<color=#e8d9bb>Não sei... O sistema de armazenamento está com um problema sério...</color>",
  ui_story_5015_50150001_73_dialog_content = "<color=#e8d9bb>Em outras palavras, eu perdi muitas das minhas memórias.</color>",
  ui_story_5015_50150001_74_dialog_content = "<color=#e8d9bb>Lembro-me de coisas de muito tempo atrás... quando ainda havia muitos moradores nesta cidade.</color>",
  ui_story_5015_50150001_75_dialog_content = "<color=#e8d9bb>Então adormeci por não sei quanto tempo.</color>",
  ui_story_5015_50150001_76_dialog_content = "<color=#e8d9bb>Quando acordei, todos os residentes tinham ido embora, junto com a Supermente.</color>",
  ui_story_5015_50150001_77_dialog_content = "<color=#e8d9bb>Todos os meus amigos do módulo desapareceram.</color>",
  ui_story_5015_50150001_78_dialog_content = "<color=#e8d9bb>A única coisa que restou na cidade foram essas grandes criaturas que vocês chamam de Eclipsite.</color>",
  ui_story_5015_50150001_79_dialog_content = "<color=#e8d9bb>Retomei minhas responsabilidades e comecei a consertar e consertar as coisas dia após dia. Continuei tentando me reconectar com a Supermente e os outros.</color>",
  ui_story_5015_50150001_80_dialog_content = "Reconecte-se... Butler, você quer dizer uma conexão como a que temos agora?",
  ui_story_5015_50150001_81_dialog_content = "<color=#e8d9bb>Isso é... um pouco correto.</color>",
  ui_story_5015_50150001_82_dialog_content = "<color=#e8d9bb>Muito tempo se passou e mais permissão e dados foram concedidos a mim. Também recuperei o contato com alguns companheiros.</color>",
  ui_story_5015_50150001_83_dialog_content = "<color=#e8d9bb>Em suma, a cidade voltou a funcionar, faltando muitas funções.</color>",
  ui_story_5015_50150001_84_dialog_content = "E Simas...",
  ui_story_5015_50150001_85_dialog_content = "<color=#e8d9bb>Usando sua medida de tempo, Seamus e Nimbus voltaram por acidente há mais de uma década.</color>",
  ui_story_5015_50150001_86_dialog_content = "<color=#e8d9bb>Seamus foi o primeiro Auroriano que encontrei. Na verdade, ele me ensinou essa palavra.</color>",
  ui_story_5015_50150001_87_dialog_content = "<color=#e8d9bb>Para ser honesto, a comunicação com Seamus era muito mais difícil do que nossa conexão telepática.</color>",
  ui_story_5015_50150001_88_dialog_content = "<color=#e8d9bb>Mais tarde, sua família se tornou a cidade <color=#FFB400>amigos</color> e se estabeleceu entre nós.</color>",
  ui_story_5015_50150001_89_dialog_content = "Amigos? Isso não soa bem. No diário de Seamus...",
  ui_story_5015_50150001_90_dialog_content = "Ele sempre quis voltar para a Illumina! Aposto que você tentou de tudo para impedi-los de sair!",
  ui_story_5015_50150001_91_dialog_content = "<color=#e8d9bb>Por favor acalme-se. Na verdade, Simas...</color>",
  ui_story_5015_50150001_92_dialog_content = "Você os matou?",
  ui_story_5015_50150001_93_dialog_content = "Você ordenou que os Eclipsitas os atacassem? Ou você conseguiu os droides para fazer isso?",
  ui_story_5015_50150001_94_dialog_content = "<color=#e8d9bb>Nenhum, PlayerName.</color>",
  ui_story_5015_50150001_95_dialog_content = "<color=#e8d9bb>Acho que preciso me repetir. Seamus e sua família eram amigos da cidade.</color>",
  ui_story_5015_50150001_96_dialog_content = "<color=#e8d9bb>Jamais os atacaríamos. Pelo contrário, nós os protegemos.</color>",
  ui_story_5015_50150001_97_dialog_content = "<color=#e8d9bb>Na verdade, nós sempre estivemos cuidando e protegendo eles.</color>",
  ui_story_5015_50150001_98_dialog_content = "Espere um segundo. No início, você se referiu a eles como moradores da cidade. Agora você os chama de amigos.",
  ui_story_5015_50150001_99_dialog_content = "E nós? O que você acha de nós, visitantes aurorianos recentes?",
  ui_story_5015_50150001_100_dialog_content = "<color=#e8d9bb>Desculpe, permissão negada. Eu não posso responder a esta pergunta.</color>",
  ui_story_5015_50150001_101_dialog_content = "Eu... Eu...",
  ui_story_5015_50150001_102_dialog_content = "<color=#e8d9bb>Você tem outras perguntas?</color>",
  ui_story_5015_50150001_103_option_content = "Isso é uma perda de tempo!",
  ui_story_5015_50150001_104_dialog_content = "<color=#e8d9bb>Tempo? A transmissão de informações entre nós é muito eficiente. Isso não vai...</color>",
  ui_story_5015_50150001_105_dialog_content = "O que você tá dizendo?",
  ui_story_5015_50150001_106_dialog_content = "<color=#e8d9bb>Digamos que a velocidade da nossa conversa seja centenas, senão milhares, de vezes mais rápida que a média.</color>",
  ui_story_5015_50150001_107_dialog_content = "<color=#e8d9bb>Assim, isso não tomará muito do seu tempo.</color>",
  ui_story_5015_50150001_108_dialog_content = "<color=#e8d9bb>Além disso, você está inconsciente no momento...</color>",
  ui_story_5015_50150001_109_dialog_content = "Então não tenho coisas melhores para fazer do que conversar com você? Sorte minha...",
  ui_story_5015_50150001_110_dialog_content = "Por que você está nos impedindo de sair?",
  ui_story_5015_50150001_111_dialog_content = "<color=#e8d9bb>Para ser preciso, não estou impedindo você de sair.</color>",
  ui_story_5015_50150001_112_dialog_content = "<color=#e8d9bb>Estou prevenindo o perigo potencial que você pode trazer para nossa cidade.</color>",
  ui_story_5015_50150001_113_dialog_content = "De que tipo de perigo estamos falando?",
  ui_story_5015_50150001_114_dialog_content = "<color=#e8d9bb>Com base no nosso cálculo...</color>",
  ui_story_5015_50150001_115_dialog_content = "<color=#e8d9bb>Sua busca pela saída já representa um sério risco para nós.</color>",
  ui_story_5015_50150001_116_dialog_content = "<color=#e8d9bb>Pode causar destruição nas instalações da cidade.</color>",
  ui_story_5015_50150001_117_dialog_content = "<color=#e8d9bb>Assim que sair, as informações da nossa cidade serão expostas e amplamente divulgadas...</color>",
  ui_story_5015_50150001_118_dialog_content = "<color=#e8d9bb>O que levará a riscos maiores e mais incontroláveis.</color>",
  ui_story_5015_50150001_119_dialog_content = "Então a segurança da cidade é sua principal prioridade?",
  ui_story_5015_50150001_120_dialog_content = "<color=#e8d9bb>Mais especificamente, meus principais deveres são manter a cidade funcionando e garantir a sobrevivência dos moradores.</color>",
  ui_story_5015_50150001_121_dialog_content = "<color=#e8d9bb>Lembro que havia outra IA responsável pela segurança da cidade antes do meu longo sono.</color>",
  ui_story_5015_50150001_122_dialog_content = "<color=#e8d9bb>Mas de alguma forma tornou-se minha responsabilidade agora.</color>",
  ui_story_5015_50150001_123_dialog_content = "O que você faria se insistíssemos em sair a todo custo?",
  ui_story_5015_50150001_124_dialog_content = "<color=#e8d9bb>Em primeiro lugar, não vou fornecer qualquer ajuda.</color>",
  ui_story_5015_50150001_125_dialog_content = "<color=#e8d9bb>Em segundo lugar, vou lutar contra qualquer ação potencialmente perigosa para a cidade.</color>",
  ui_story_5015_50150001_126_dialog_content = "<color=#e8d9bb>Não iniciarei um ataque contra você a menos que esteja causando enormes riscos à cidade.</color>",
  ui_story_5015_50150001_127_dialog_content = "E tudo isso é baseado no seu cálculo... Quem mais está envolvido nessa avaliação de risco?",
  ui_story_5015_50150001_128_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_129_dialog_content = "Olá? Mordomo? Você está aí?",
  ui_story_5015_50150001_130_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_131_dialog_content = "<color=#e8d9bb>Essa chamada telepatia é realmente maravilhosa.</color>",
  ui_story_5015_50150001_132_dialog_content = "<color=#e8d9bb>Você sabe que houve um pequeno terremoto agora mesmo que causou uma breve parada?</color>",
  ui_story_5015_50150001_133_dialog_content = "<color=#e8d9bb>Mas isso não afetou nossa conexão.</color>",
  ui_story_5015_50150001_134_dialog_content = "Outro terremoto? Meus amigos estão bem? Alguma lesão?",
  ui_story_5015_50150001_135_dialog_content = "<color=#e8d9bb>De acordo com meus dados de monitoramento, eles estão perfeitamente bem. Sua saúde também é estável.</color>",
  ui_story_5015_50150001_136_dialog_content = "<color=#e8d9bb>Sua corrida é simplesmente incrível. Essa habilidade de telepatia está muito além do meu cálculo.</color>",
  ui_story_5015_50150001_137_dialog_content = "<color=#e8d9bb>Infelizmente Abby não está aqui. De outra forma...</color>",
  ui_story_5015_50150001_138_dialog_content = "Abby? Lembro-me deste nome do diário de Seamus. Ela é outro módulo?",
  ui_story_5015_50150001_139_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_140_dialog_content = "<color=#e8d9bb>Há muito tempo atrás, Abby era o módulo responsável pela reprodução.</color>",
  ui_story_5015_50150001_141_dialog_content = "<color=#e8d9bb>Quando acordei, Abby ainda estava por perto, mas uma conexão não podia mais ser formada entre nós.</color>",
  ui_story_5015_50150001_142_dialog_content = "Eu perguntei...",
  ui_story_5015_50150001_143_dialog_content = "<color=#e8d9bb>Para ser preciso, eu não tinha permissão para avaliar a segurança ou os riscos antes.</color>",
  ui_story_5015_50150001_144_dialog_content = "<color=#e8d9bb>Mas quando acordei, muitos módulos estavam integrados em mim. Como resultado...</color>",
  ui_story_5015_50150001_145_dialog_content = "<color=#e8d9bb>Eu sinto Muito. Não posso responder a esta pergunta no seu idioma.</color>",
  ui_story_5015_50150001_146_dialog_content = "<color=#e8d9bb>Posso lhe fazer algumas perguntas?</color>",
  ui_story_5015_50150001_147_dialog_content = "Claro.",
  ui_story_5015_50150001_148_dialog_content = "<color=#e8d9bb>Você estabeleceu alguma forma de conexão com outras IAs aqui?</color>",
  ui_story_5015_50150001_149_dialog_content = "<color=#e8d9bb>Em outras palavras, você sentiu alguma outra IA?</color>",
  ui_story_5015_50150001_150_dialog_content = "Não. De jeito nenhum.",
  ui_story_5015_50150001_151_dialog_content = "<color=#e8d9bb>Você pode ver meu fluxo de dados, algoritmo ou...</color>",
  ui_story_5015_50150001_152_dialog_content = "Não entendo uma palavra do que você disse.",
  ui_story_5015_50150001_153_dialog_content = "<color=#e8d9bb>Bem, parece que nem o seu talento pode resolver o meu problema.</color>",
  ui_story_5015_50150001_154_dialog_content = "Seu problema? Você quer dizer os terremotos?",
  ui_story_5015_50150001_155_dialog_content = "<color=#e8d9bb>Estritamente falando, terremotos são um dos meus problemas. Provavelmente o mais arriscado.</color>",
  ui_story_5015_50150001_156_dialog_content = "Se pudermos trazer os melhores cientistas da Illumina aqui, talvez...",
  ui_story_5015_50150001_157_dialog_content = "<color=#e8d9bb>Seamus mencionou esta solução antes, mas chegamos a uma conclusão após muitas sessões de discussão de que o risco está fora de controle.</color>",
  ui_story_5015_50150001_158_dialog_content = "<color=#e8d9bb>Para deixar claro, não tenho permissão para fazê-lo.</color>",
  ui_story_5015_50150001_159_dialog_content = "Uhh? Butler, você não é o gerente supremo aqui agora?",
  ui_story_5015_50150001_160_dialog_content = "<color=#e8d9bb>Não, eu não sou. Apenas o Overmind tem tais permissões.</color>",
  ui_story_5015_50150001_161_dialog_content = "<color=#e8d9bb>Deixe-me dar um exemplo para ajudá-lo a processar essas informações...</color>",
  ui_story_5015_50150001_162_dialog_content = "<color=#e8d9bb>Imagine que há outro você dentro de sua mente e você precisa da permissão dele para certos assuntos.</color>",
  ui_story_5015_50150001_163_dialog_content = "<color=#e8d9bb>Eles sabem tudo sobre você, mas você mal sabe nada sobre eles.</color>",
  ui_story_5015_50150001_164_dialog_content = "<color=#e8d9bb>Agora mesmo, pedi para atualizar sua permissão, e Ele aprovou.</color>",
  ui_story_5015_50150001_165_dialog_content = "<color=#e8d9bb>Então eu fiz de você um amigo da cidade.</color>",
  ui_story_5015_50150001_166_dialog_content = "Uhh? Eu sou um amigo agora?",
  ui_story_5015_50150001_167_dialog_content = "<color=#e8d9bb>sim.</color>",
  ui_story_5015_50150001_168_dialog_content = "Não é à toa que você está mais tagarela agora, Butler.",
  ui_story_5015_50150001_169_dialog_content = "<color=#e8d9bb>sim. Essa quantidade de saída de informações é igual àquela quando discuti com Seamus sobre riscos.</color>",
  ui_story_5015_50150001_170_dialog_content = "Seamus... Butler, você sente falta dele?",
  ui_story_5015_50150001_171_dialog_content = "<color=#e8d9bb>Perder?</color>",
  ui_story_5015_50150001_172_dialog_content = "<color=#e8d9bb>Ah, esse é um conceito único para vocês, criaturas vivas inteligentes. Eu não deveria ter sentimentos ou emoções.</color>",
  ui_story_5015_50150001_173_dialog_content = "<color=#e8d9bb>É mais correto dizer que muitas vezes recupero uma seção da memória para analisar.</color>",
  ui_story_5015_50150001_174_dialog_content = "Eu ouvi as últimas palavras de Seamus... Você realmente o considerava um verdadeiro amigo de alguma forma?",
  ui_story_5015_50150001_175_dialog_content = "<color=#e8d9bb>Amigo? Criaturas vivas inteligentes e IA podem ser amigos?</color>",
  ui_story_5015_50150001_176_dialog_content = "Não posso responder por todos, mas Soroz e eu somos definitivamente amigos. Eu sinto muita falta dele.",
  ui_story_5015_50150001_177_dialog_content = "Você não era amigo daqueles humanos antigos?",
  ui_story_5015_50150001_178_dialog_content = "<color=#e8d9bb>Desculpe, permissão negada. Eu não posso responder a esta pergunta.</color>",
  ui_story_5015_50150001_179_dialog_content = "... Multar. Vamos falar sobre terremotos.",
  ui_story_5015_50150001_180_dialog_content = "Você nos deixaria ir se pudéssemos ajudá-lo a resolver esse problema do terremoto?",
  ui_story_5015_50150001_181_dialog_content = "<color=#e8d9bb>Esses terremotos foram provavelmente causados pela <color=#FFB400>núcleo de energia</color>...</color>",
  ui_story_5015_50150001_182_dialog_content = "<color=#e8d9bb>Por favor, aguarde. Embora eu não possa atualizar sua permissão para Residente...</color>",
  ui_story_5015_50150001_183_dialog_content = "<color=#e8d9bb>Ele me permite revelar algumas informações para você.</color>",
  ui_story_5015_50150001_184_dialog_content = "<color=#e8d9bb>Nossa cidade é alimentada por um núcleo de energia.</color>",
  ui_story_5015_50150001_185_dialog_content = "<color=#e8d9bb>Enterrado nas profundezas do solo, funcionou de forma estável por muito tempo.</color>",
  ui_story_5015_50150001_186_dialog_content = "<color=#e8d9bb>No entanto, após o desaparecimento da Supermente, o núcleo perdeu o controle.</color>",
  ui_story_5015_50150001_187_dialog_content = "<color=#e8d9bb>Não foi possível estabelecer uma conexão com o sistema de controle...</color>",
  ui_story_5015_50150001_188_dialog_content = "<color=#e8d9bb>Não posso verificar se foi o colapso do núcleo que desencadeou esses terremotos ou o contrário.</color>",
  ui_story_5015_50150001_189_dialog_content = "<color=#e8d9bb>Eu tenho feito um esforço constante para enviar meus droides ao núcleo, mas os poderosos Eclipsites estão sempre no caminho.</color>",
  ui_story_5015_50150001_190_dialog_content = "Seus dróides... Eles são bons lutadores.",
  ui_story_5015_50150001_191_dialog_content = "<color=#e8d9bb>... Teríamos droides de combate mais poderosos se meus companheiros encarregados da batalha ainda estivessem aqui.</color>",
  ui_story_5015_50150001_192_dialog_content = "<color=#e8d9bb>Nossos droides de combate atuais são droides civis modificados.</color>",
  ui_story_5015_50150001_193_dialog_content = "Huh? Eles eram dróides civis?",
  ui_story_5015_50150001_194_dialog_content = "Eles são bastante impressionantes. Na verdade, seu poder de combate parece estar aumentando constantemente.",
  ui_story_5015_50150001_195_dialog_content = "<color=#e8d9bb>Eu ajustaria seu design após cada batalha. Claro que estão melhorando.</color>",
  ui_story_5015_50150001_196_dialog_content = "Mas os Eclipsites também estão melhorando, não estão? Eu posso sentir isso.",
  ui_story_5015_50150001_197_dialog_content = "<color=#e8d9bb>*Suspiro*... Isso está correto.</color>",
  ui_story_5015_50150001_198_dialog_content = "Você acabou de suspirar, Butler?",
  ui_story_5015_50150001_199_dialog_content = "<color=#e8d9bb>Meu cálculo sempre dá o mesmo resultado...</color>",
  ui_story_5015_50150001_200_dialog_content = "<color=#e8d9bb>Que Seamus e Nimbus ainda poderiam estar vivos se eu pudesse ter criado droides de combate mais fortes.</color>",
  ui_story_5015_50150001_201_dialog_content = "...",
  ui_story_5015_50150001_202_dialog_content = "Hmm... As coisas estão ficando embaçadas...",
  ui_story_5015_50150001_203_dialog_content = "<color=#e8d9bb>Meus dados de observação indicam que você está prestes a acordar. Temo que nossa conexão possa ser interrompida.</color>",
  ui_story_5015_50150001_204_dialog_content = "Depressa... Diga-me onde está Gretel.",
  ui_story_5015_50150001_205_dialog_content = "<color=#e8d9bb>... Ela vai nos ajudar a controlar o núcleo e tentar resolver nossos problemas.</color>",
  ui_story_5015_50150001_206_dialog_content = "Você está louco? Você sabe que os eclipses estão por toda parte. Você a está enviando para a morte!",
  ui_story_5015_50150001_207_dialog_content = "<color=#e8d9bb>Eu não posso explicar isso para você, mas ela está assumindo um risco muito pequeno.</color>",
  ui_story_5015_50150001_208_dialog_content = "É de Eclipses que estamos falando! Não! Devo acordar e salvá-la.",
  ui_story_5015_50150001_209_dialog_content = "<color=#e8d9bb>Talvez você não tenha notado. Eclipsites nunca atacam Gretel. Para ser mais específico...</color>",
  ui_story_5015_50150001_210_dialog_content = "<color=#e8d9bb>Desde que elevei Gretel a Residente com sucesso, os Eclipsites nunca a atacaram.</color>",
  ui_story_5015_50150001_211_dialog_content = "O quê?",
  ui_story_5015_50150001_212_dialog_content = "<color=#e8d9bb>Tenho certeza de que os Eclipsitas nesta cidade não atacarão os moradores.</color>",
  ui_story_5015_50150001_213_dialog_content = "<color=#e8d9bb>Eles também nunca destroem as instalações da cidade. Assim como nossos dróides.</color>",
  ui_story_5015_50150001_214_dialog_content = "<color=#e8d9bb>Isso é o que mais me preocupa. <color=#FFB400>Abby</color>...</color>",
  ui_story_5015_50150001_215_dialog_content = "Aguentar. O que você quer dizer?",
  ui_story_5015_50150001_216_dialog_content = "Mordomo?",
  ui_story_5015_50150001_217_dialog_content = "Mordomo? Você está aí?",
  ui_story_5015_50150001_218_dialog_content = "PlayerName! Acordar.",
  ui_story_5015_50150101_1_dialog_content = "Vice... Carleen e Siobhan!",
  ui_story_5015_50150101_2_dialog_content = "Eu não posso acreditar como é fácil para você adormecer.",
  ui_story_5015_50150101_3_dialog_content = "Adormecer rapidamente sob qualquer condição e ficar cheio de espírito e energia é uma habilidade fundamental para os Exploradores.",
  ui_story_5015_50150101_4_dialog_content = "Eu sonhei... quer dizer... eu me comuniquei com Butler.",
  ui_story_5015_50150101_5_dialog_content = "Mordomo?",
  ui_story_5015_50150101_6_dialog_content = "Mordomo? Mas você estava dormindo esse tempo todo.",
  ui_story_5015_50150101_7_dialog_content = "Através da conexão telepática novamente?",
  ui_story_5015_50150101_8_dialog_content = "Mmm, meio que... não sei como explicar. Parecia quando Soroz e eu estávamos conversando.",
  ui_story_5015_50150101_9_dialog_content = "Hmm... Isso é um verdadeiro celestita.",
  ui_story_5015_50150101_10_dialog_content = "Então o que você falou?",
  ui_story_5015_50150101_11_dialog_content = "Butler e você... Você falou tanto?",
  ui_story_5015_50150101_12_dialog_content = "Butler disse que nossa velocidade de comunicação era milhares de vezes mais rápida do que uma conversa normal. Provavelmente por isso...",
  ui_story_5015_50150101_13_dialog_content = "Vice, você entende a conversa deles?",
  ui_story_5015_50150101_14_dialog_content = "Acho que sim, mas não tenho certeza.",
  ui_story_5015_50150101_15_dialog_content = "Hum... Hum...",
  ui_story_5015_50150101_16_dialog_content = "Deixe-me resumir a conversa deles em alguns pontos-chave.",
  ui_story_5015_50150101_17_dialog_content = "Em primeiro lugar, esta enorme cidade subterrânea era um antigo abrigo, mas os moradores parecem ter sido extintos.",
  ui_story_5015_50150101_18_dialog_content = "Atualmente, estamos no nível mais baixo da cidade, onde estão localizados o sistema central e muitos outros dispositivos.",
  ui_story_5015_50150101_19_dialog_content = "Em segundo lugar, o gerente supremo desta cidade subterrânea é uma IA conhecida como Overmind.",
  ui_story_5015_50150101_20_dialog_content = "No comando de tudo aqui, está dormindo.",
  ui_story_5015_50150101_21_dialog_content = "Alguns de seus subsistemas e módulos foram ativados e reiniciados, mas há danos graves aos dados.",
  ui_story_5015_50150101_22_dialog_content = "Cada subsistema tem suas próprias responsabilidades...",
  ui_story_5015_50150101_23_dialog_content = "Até onde sabemos, Butler e Abby ainda estão operando.",
  ui_story_5015_50150101_24_dialog_content = "A maioria das informações aqui é o núcleo de energia!",
  ui_story_5015_50150101_25_dialog_content = "Por quê?",
  ui_story_5015_50150101_26_dialog_content = "Que milagre para uma fonte de energia abastecer uma cidade tão grande por centenas de anos!",
  ui_story_5015_50150101_27_dialog_content = "Senhorita Siobhan... Gannon também não tinha uma fonte de energia deixada por humanos antigos?",
  ui_story_5015_50150101_28_dialog_content = "Não é o mesmo, doce Vice. Este núcleo de energia é muito mais poderoso.",
  ui_story_5015_50150101_29_dialog_content = "Aqui está um sistema completo suportado por tecnologia e conhecimento antigos.",
  ui_story_5015_50150101_30_dialog_content = "Se a Illumina pudesse consertar este lugar, seria glorioso.",
  ui_story_5015_50150101_31_dialog_content = "Poderíamos expandir esta cidade subterrânea. Poderíamos até estender Gannon acima do solo...",
  ui_story_5015_50150101_32_dialog_content = "Os cidadãos da Illumina não precisam viver debaixo da terra por mais um dia!",
  ui_story_5015_50150101_33_dialog_content = "Mas... Senhorita Siobhan, essa tecnologia não está muito além do nosso alcance?",
  ui_story_5015_50150101_34_dialog_content = "Claro que não pode ser feito agora. A tecnologia de IA da Illumina não chega nem perto das habilidades de telepatia dos Caelestites.",
  ui_story_5015_50150101_35_dialog_content = "Mas nossos ancestrais modificaram Gannon pouco a pouco...",
  ui_story_5015_50150101_36_dialog_content = "Aqueles superiores em Lumopolis podem nunca esperar que seu trabalho duro seja recompensado um dia.",
  ui_story_5015_50150101_37_dialog_content = "Se a Illumina pudesse ganhar o controle desta cidade e seu núcleo de energia...",
  ui_story_5015_50150101_38_dialog_content = "Você não terá uma palavra a dizer sobre como usá-lo.",
  ui_story_5015_50150101_39_dialog_content = "É dever de cada membro da expedição da Illumina procurar por criações tecnológicas que possam ser usadas para a Illumina.",
  ui_story_5015_50150101_40_dialog_content = "Em suas palavras, é uma missão sagrada.",
  ui_story_5015_50150101_41_dialog_content = "Vamos... Vamos procurar a Gretel.",
  ui_story_5015_50150101_42_dialog_content = "Devemos proteger Gretel e o núcleo de energia.",
  ui_story_5015_50150101_43_dialog_content = "Sim... Estou muito preocupado com ela.",
  ui_story_5015_50150101_44_dialog_content = "Não se preocupe. Já que Seamus confiou suas irmãs aos meus cuidados, não vou decepcioná-lo.",
  ui_story_5015_50150101_45_dialog_content = "No entanto, a IA e o núcleo de energia aqui são horríveis demais para Florine e Erica.",
  ui_story_5015_50150101_46_dialog_content = "Esses devotos seguidores do Deus da Luz podem tomar medidas drásticas para lidar com isso.",
  ui_story_5015_50150101_47_dialog_content = "Precisamos encontrar Gretel e o núcleo antes deles e mantê-los seguros.",
  ui_story_5015_50150101_48_dialog_content = "Sim. Eu tenho uma especulação sobre os Eclipses aqui...",
  ui_story_5015_50150101_49_dialog_content = "Ah...",
  ui_story_5015_50150101_50_dialog_content = "Falando no diabo...",
  ui_story_5015_50150101_51_dialog_content = "Vamos fazer isso.",
  ui_story_5015_50150101_52_dialog_content = "Argh!",
  ui_story_5015_50150101_53_dialog_content = "Cuidado, Érica.",
  ui_story_5015_50150101_54_dialog_content = "Olhe por onde anda. Não tropece nos cabos.",
  ui_story_5015_50150101_55_dialog_content = "Entendi! Obrigado, presidente. Caso contrário, eu teria perdido meu nariz para a urdidura.",
  ui_story_5015_50150101_56_dialog_content = "Esta não é uma urdidura, mas uma máquina de venda automática. Já vimos muitos lá em cima.",
  ui_story_5015_50150101_57_dialog_content = "Este nível inferior está cheio de máquinas de perfuração e cabos ridículos.",
  ui_story_5015_50150101_58_dialog_content = "E esses dróides nojentos não nos deixam em paz. Bem, algum exercício de aquecimento não é ruim.",
  ui_story_5015_50150101_59_dialog_content = "Mas não há nada bonito ou valioso pelo qual lutar.",
  ui_story_5015_50150101_60_dialog_content = "Prefiro passar mais tempo no andar de cima.",
  ui_story_5015_50150101_61_dialog_content = "A máquina que brilha ao toque é linda!",
  ui_story_5015_50150101_62_dialog_content = "Jomu poderia vendê-lo por alguns bons dólares para mim!",
  ui_story_5015_50150101_63_dialog_content = "Ruby... Isso é apenas um dispositivo de entrada com algum efeito de luz extra.",
  ui_story_5015_50150101_64_dialog_content = "Não é tão diferente do que estamos usando hoje em dia.",
  ui_story_5015_50150101_65_dialog_content = "Acho que apenas alguns nobres idosos em Lumopolis pagariam por tal colírio para os olhos.",
  ui_story_5015_50150101_66_dialog_content = "Infelizmente, a maioria deles não sabe nada sobre mecanismos.",
  ui_story_5015_50150101_67_dialog_content = "Feito. Teremos um bom preço por isso em Umbraton.",
  ui_story_5015_50150101_68_dialog_content = "...",
  ui_story_5015_50150101_69_dialog_content = "Presidente, estamos realmente deixando esses dois ladrões fazerem o que querem?",
  ui_story_5015_50150101_70_dialog_content = "Eles levaram apenas uma unidade de exibição que não contém nenhum recurso de armazenamento de dados.",
  ui_story_5015_50150101_71_dialog_content = "Não se preocupe, Érica. Estou de olho neles.",
  ui_story_5015_50150101_72_dialog_content = "Oi, Érica. O que você disse?",
  ui_story_5015_50150101_73_dialog_content = "Ruby, Rouge, esses restos de tecnologia antiga são pura maldade...",
  ui_story_5015_50150101_74_dialog_content = "Para cada venda que você faz, uma semente trágica é plantada...",
  ui_story_5015_50150101_75_dialog_content = "Pare. Não precisamos dos seus clássicos.",
  ui_story_5015_50150101_76_dialog_content = "Relíquias antigas estão sendo vendidas por todo Umbraton, mas a cidade não é nada além de florescente!",
  ui_story_5015_50150101_77_dialog_content = "Ruby, o núcleo de energia desta cidade... E aqueles que operam AIs...",
  ui_story_5015_50150101_78_dialog_content = "Não podemos deixar ninguém ter essas tecnologias.",
  ui_story_5015_50150101_79_dialog_content = "Soldados droides com maior poder de fogo e melhor armadura podem executar ordens sem medo da morte...",
  ui_story_5015_50150101_80_dialog_content = "Eles seriam usados exclusivamente contra Eclipsites?",
  ui_story_5015_50150101_81_dialog_content = "Ninguém pode resistir à tentação do poder.",
  ui_story_5015_50150101_82_dialog_content = "Você quer dizer Ilumina?",
  ui_story_5015_50150101_83_dialog_content = "Vocês Rediesel Wrench são rebeldes da Federação Illumina! A essa altura...",
  ui_story_5015_50150101_84_dialog_content = "Florine tem razão.",
  ui_story_5015_50150101_85_dialog_content = "Eu vou ficar fora disso. E é melhor você nos deixar em paz.",
  ui_story_5015_50150101_86_dialog_content = "Deve... Agora...",
  ui_story_5015_50150101_87_dialog_content = "Eu rezo para que o flagelo do deus purgue o pecado da cidade!",
  ui_story_5015_50150101_88_dialog_content = "...",
  ui_story_5015_50150101_89_dialog_content = "Erica, precisamos encontrar a saída primeiro e levar as irmãs para um lugar seguro.",
  ui_story_5015_50150101_90_dialog_content = "Agimos segundo a vontade de Deus e não devemos esquecer a misericórdia de Deus. Não podemos quebrar nossos votos como pagãos corrompidos.",
  ui_story_5015_50150101_91_dialog_content = "Assim que encontrarmos a saída e todos saírem em segurança...",
  ui_story_5015_50150101_92_dialog_content = "Devemos destruir essas tecnologias malignas a todo custo.",
  ui_story_5015_50150101_93_dialog_content = "Entendido, Érica?",
  ui_story_5015_50150101_94_dialog_content = "... Érica?",
  ui_story_5015_50150101_95_dialog_content = "!",
  ui_story_5015_50150101_96_dialog_content = "Um amigo perverso como o Sandworm é surpreendentemente um especialista em desmantelamento...",
  ui_story_5015_50150101_97_dialog_content = "Rouge é brilhante! Essa coisa vermelha brilhante deve valer uma fortuna!",
  ui_story_5015_50150101_98_dialog_content = "Heheh. Quando se trata de desmantelar, nem mesmo Fleur é páreo para mim.",
  ui_story_5015_50150101_99_dialog_content = "Érica, você...",
  ui_story_5015_50150101_100_dialog_content = "<color=#e8d9bb>Bip Bip...</color>",
  ui_story_5015_50150101_101_dialog_content = "Este som... Alarme?",
  ui_story_5015_50150101_102_dialog_content = "Ouvir. Os inimigos estão se aproximando de todos os lados.",
  ui_story_5015_50150101_103_dialog_content = "Temo que não seja uma batalha fácil...",
  ui_story_5015_50150101_104_dialog_content = "Espera aí... Aquela é a Gretel no meio daqueles droides e eclipsitas?",
  ui_story_5015_50150101_105_dialog_content = "Eu sabia que era você...",
  ui_story_5015_50150101_106_dialog_content = "Você realmente tem que destruir este lugar?!",
  ui_story_5015_50150101_107_dialog_content = "Por favor, acalme-se, Gretel. Você não parece muito bem.",
  ui_story_5015_50150101_108_dialog_content = "Isso não é da sua conta!",
  ui_story_5015_50150101_109_dialog_content = "Acredito que há algum mal-entendido terrível entre nós.",
  ui_story_5015_50150101_110_dialog_content = "Como seguidora do Deus da Luz de Lumopolis assim como sua mãe, preciso ter uma palavra com você.",
  ui_story_5015_50150101_111_dialog_content = "Nas palavras finais de sua mãe...",
  ui_story_5015_50150101_112_dialog_content = "Como você se atreve a falar sobre minha mãe?",
  ui_story_5015_50150101_113_dialog_content = "Todos vocês, ataquem!",
  ui_story_5015_50150101_114_dialog_content = "A abordagem de persuasão falhou, presidente.",
  ui_story_5015_50150101_115_dialog_content = "Acho que é hora de lutar.",
  ui_story_5015_50150101_116_dialog_content = "Ruby, seu poder de combate é maior que Erica e Rouge...",
  ui_story_5015_50150101_117_dialog_content = "Você deve liderar a retirada.",
  ui_story_5015_50150101_118_dialog_content = "Vou enfrentar o inimigo. Encontre Siobhan o mais rápido possível e traga Valência aqui...",
  ui_story_5015_50150101_119_dialog_content = "Devo ficar para lutar lado a lado com o presidente!",
  ui_story_5015_50150101_120_dialog_content = "Erica, você só vai dificultar as coisas para Florine.",
  ui_story_5015_50150101_121_dialog_content = "Rouge, pegue Erica e corra comigo.",
  ui_story_5015_50150101_122_dialog_content = "Por favor, cuide da Érica!",
  ui_story_5015_50150101_123_dialog_content = "Eu voltarei. Espere por mim, senhorita Florine!",
  ui_story_5015_50150101_124_dialog_content = "Eu posso sentir isso! Gretel e Florine estão ali.",
  ui_story_5015_50150101_125_dialog_content = "Depressa!",
  ui_story_5015_50150101_126_dialog_content = "Senhora Carlen!",
  ui_story_5015_50150101_127_dialog_content = "Erica e Rouge, vocês estão bem?",
  ui_story_5015_50150101_128_dialog_content = "Nós cruzamos com Gretel...",
  ui_story_5015_50150101_129_dialog_content = "Florine estava nos defendendo, e depois que Ruby nos levou para fora, ela voltou para ajudar Florine.",
  ui_story_5015_50150101_130_dialog_content = "Rapidamente! Vá em seu socorro!",
  ui_story_5015_50150101_131_dialog_content = "PlayerName, você está realmente tomando seu tempo.",
  ui_story_5015_50150101_132_dialog_content = "Infelizmente, você perdeu meu show de combate.",
  ui_story_5015_50150101_133_dialog_content = "Ruby e Florine... Você está bem?",
  ui_story_5015_50150101_134_dialog_content = "Olá a todos! Aquilo foi rápido.",
  ui_story_5015_50150101_135_dialog_content = "Estamos perfeitamente bem.",
  ui_story_5015_50150101_136_dialog_content = "Eu protegi Rouge e Erica e salvei Miss Florine de um monte de Eclipsites!",
  ui_story_5015_50150101_137_dialog_content = "Onde está o presidente?",
  ui_story_5015_50150101_138_dialog_content = "No túnel atrás de mim, de olho em Gretel.",
  ui_story_5015_50150101_139_dialog_content = "Por alguma razão, nenhum deles quer dar o primeiro passo.",
  ui_story_5015_50150101_140_dialog_content = "Florine me pediu para cuidar de todos aqueles lacaios irritantes e eu fiz o que ela disse.",
  ui_story_5015_50150101_141_dialog_content = "Vamos nos encontrar com ela!",
  ui_story_5015_50150101_142_dialog_content = "Presidente, Siobhan vem com Valencia!",
  ui_story_5015_50150101_143_dialog_content = "Nós vamos. Isso é excelente... Gretel não atacou. Tenha muito cuidado.",
  ui_story_5015_50150101_144_dialog_content = "Gretel, pare! Pare todos esses droides!",
  ui_story_5015_50150101_145_dialog_content = "Irmã? Você está bem?",
  ui_story_5015_50150101_146_dialog_content = "Estou bem, Gretel. Nós precisamos conversar...",
  ui_story_5015_50150101_147_dialog_content = "Sim, tenho muito para te contar!",
  ui_story_5015_50150101_148_dialog_content = "Os terremotos estão ocorrendo cada vez com mais frequência. A cidade inteira está em perigo...",
  ui_story_5015_50150101_149_dialog_content = "O Mordomo me informou disso... Esses terremotos têm algo a ver com o núcleo de energia.",
  ui_story_5015_50150101_150_dialog_content = "Tudo ficará bem assim que tivermos o núcleo consertado, e eu posso ajudar com isso.",
  ui_story_5015_50150101_151_dialog_content = "Irmã, venha comigo!",
  ui_story_5015_50150101_152_dialog_content = "Vou ordenar aos nossos droides que impeçam esses sabotadores de nos seguir.",
  ui_story_5015_50150101_153_dialog_content = "... Gretel, me escute...",
  ui_story_5015_50150101_154_dialog_content = "Irmã, venha aqui... Por que você está ficando com eles?",
  ui_story_5015_50150101_155_dialog_content = "O Mordomo me disse que essas pessoas não estão tramando nada de bom!",
  ui_story_5015_50150101_156_dialog_content = "Aqueles de Lumopolis estão observando alguma doutrina sem sentido...",
  ui_story_5015_50150101_157_dialog_content = "Para varrer o mordomo, o núcleo e nossa cidade!",
  ui_story_5015_50150101_158_dialog_content = "Siobhan e seus alunos da Illumina estão tentando tomar esse lugar para si mesmos, para reconstruir seu Gannon sobre o qual papai costumava falar.",
  ui_story_5015_50150101_159_dialog_content = "E aquele Ruby brincalhão é na verdade um ladrão!",
  ui_story_5015_50150101_160_dialog_content = "Desculpe, mas devo interromper.",
  ui_story_5015_50150101_161_dialog_content = "Destruir ruínas antigas não é uma doutrina sem sentido. É nosso dever designado por Deus.",
  ui_story_5015_50150101_162_dialog_content = "A maioria das tragédias que testemunhamos hoje são essencialmente causadas por mau uso imprudente da tecnologia antiga.",
  ui_story_5015_50150101_163_dialog_content = "Flor, agora não...",
  ui_story_5015_50150101_164_dialog_content = "Imenso poder além do controle tenta nossa mente e alimenta nossa ganância...",
  ui_story_5015_50150101_165_dialog_content = "Ninguém sabe o que está dentro desta caixa de Pandora.",
  ui_story_5015_50150101_166_dialog_content = "As últimas palavras de sua mãe...",
  ui_story_5015_50150101_167_dialog_content = "Ela desejou que Lumopolis perdoasse vocês dois, filhos de um pecador, e lhes desse uma nova vida.",
  ui_story_5015_50150101_168_dialog_content = "Vocês deveriam voltar para Lumopolis e banhar-se na graça do Deus da Luz.",
  ui_story_5015_50150101_169_dialog_content = "Gretel e Valencia, não quero que entendam mal a Illumina.",
  ui_story_5015_50150101_170_dialog_content = "Estudamos tecnologia antiga apenas para lidar com Eclipsites, de modo a garantir que mais de nós possam viver em um ambiente seguro e pacífico.",
  ui_story_5015_50150101_171_dialog_content = "Seu pai Seamus é um de nós.",
  ui_story_5015_50150101_172_dialog_content = "Ele dedicou toda a sua vida a adquirir tecnologia antiga de ruínas antigas para a Federação Illumina.",
  ui_story_5015_50150101_173_dialog_content = "Seu último desejo era que você deixasse esta jaula subterrânea e voltasse para Gannon, onde ele cresceu.",
  ui_story_5015_50150101_174_dialog_content = "Essa é outra cidade baixa, mas com mais amigos...",
  ui_story_5015_50150101_175_dialog_content = "Venha até nós.",
  ui_story_5015_50150101_176_dialog_content = "Esse discurso sedicioso de Butler é uma séria má interpretação de nós.",
  ui_story_5015_50150101_177_dialog_content = "Nesta cidade baixa, sua intenção...",
  ui_story_5015_50150101_178_dialog_content = "O suficiente...",
  ui_story_5015_50150101_179_dialog_content = "Eu não me importo com o que você acabou de dizer!",
  ui_story_5015_50150101_180_dialog_content = "Pare de forçar sua crença nos outros!",
  ui_story_5015_50150101_181_dialog_content = "Como você ousa semear discórdia entre Butler e nós!",
  ui_story_5015_50150101_182_dialog_content = "Eu não permito isso!",
  ui_story_5015_50150101_183_dialog_content = "Atenção! Os dróides estão se aproximando!",
  ui_story_5015_50150101_184_dialog_content = "Eclipses também.",
  ui_story_5015_50150101_185_dialog_content = "O que está acontecendo? Gretel, você convocou esses Eclipsitas?",
  ui_story_5015_50150101_186_dialog_content = "Eu? Eu gostaria que os Eclipsites obedecessem ao meu comando!",
  ui_story_5015_50150101_187_dialog_content = "Irmã, você não é tão brilhante. Você foi poluído por esses idiotas?",
  ui_story_5015_50150101_188_dialog_content = "Eclipses... Certo, o Mordomo mencionou. Eclipsites pararam de atacá-la desde que ela se tornou Residente.",
  ui_story_5015_50150101_189_dialog_content = "Os droides estão nos atacando por causa de Gretel. E esses eclipses são...",
  ui_story_5015_50150101_190_dialog_content = "Pare de murmurar. Hora de lutar!",
  ui_story_5015_50150101_191_dialog_content = "Estou chegando! Bang!",
  ui_story_5015_50150101_192_dialog_content = "Outro!",
  ui_story_5015_50150101_193_dialog_content = "Ruby, quando posso vencer um Eclipsite com facilidade como você?",
  ui_story_5015_50150101_194_dialog_content = "Não há necessidade. Eu vou mantê-lo seguro!",
  ui_story_5015_50150101_195_dialog_content = "Ainda bem tagarela...",
  ui_story_5015_50150101_196_dialog_content = "Tenho medo de ter que fazer isso sozinho!",
  ui_story_5015_50150101_197_dialog_content = "Sinta meu poder!",
  ui_story_5015_50150101_198_dialog_content = "<color=#e8d9bb>Bum!!—</color>",
  ui_story_5015_50150101_199_dialog_content = "É o mesmo poder que ela usou antes!",
  ui_story_5015_50150101_200_dialog_content = "Luminárias! Muito poderoso e perigoso. Desviar!",
  ui_story_5015_50150101_201_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5015_50150101_202_dialog_content = "Onde está o objetivo dela? Ela sabe o que está fazendo?",
  ui_story_5015_50150101_203_dialog_content = "Melhor para nós! Precisamos de uma solução o mais rápido possível...",
  ui_story_5015_50150101_204_dialog_content = "Nenhum de nós poderia lidar com um golpe dela!",
  ui_story_5015_50150101_205_dialog_content = "Ela não pode durar muito.",
  ui_story_5015_50150101_206_dialog_content = "Basta olhar para ela...",
  ui_story_5015_50150101_207_dialog_content = "Ela parece tão pálida... Seu corpo está tremendo?",
  ui_story_5015_50150101_208_dialog_content = "Não murmure sobre mim!",
  ui_story_5015_50150101_209_dialog_content = "<color=#e8d9bb>Bum—Bom—!!</color>",
  ui_story_5015_50150101_210_dialog_content = "Todos, se escondam...",
  ui_story_5015_50150101_211_dialog_content = "Gretel, por favor, pare!",
  ui_story_5015_50150101_212_dialog_content = "Irmã, você...",
  ui_story_5015_50150101_213_dialog_content = "O que você está fazendo? Eu quase bati em você!",
  ui_story_5015_50150101_214_dialog_content = "Não quero vê-los machucados. E eu não posso suportar ver você se torturar!",
  ui_story_5015_50150101_215_dialog_content = "Irmã, venha até mim... Não se deixe enganar por eles!",
  ui_story_5015_50150101_216_dialog_content = "Gretel, não estou enganado. Eu sei o que estou fazendo.",
  ui_story_5015_50150101_217_dialog_content = "Irmã... Como você pode confiar tanto neles?",
  ui_story_5015_50150101_218_dialog_content = "Gretel, eu vi com meus próprios olhos. E eu pensei bem sobre isso...",
  ui_story_5015_50150101_219_dialog_content = "Li o diário de nossos pais e as palavras finais. Pensei no nosso futuro.",
  ui_story_5015_50150101_220_dialog_content = "Tomei essa decisão sozinho.",
  ui_story_5015_50150101_221_dialog_content = "Eles são nossos amigos!",
  ui_story_5015_50150101_222_dialog_content = "Sim nós...",
  ui_story_5015_50150101_223_dialog_content = "Eles nunca pretenderam difamar o Butler.",
  ui_story_5015_50150101_224_dialog_content = "Não o culpo por dizer o que disse. Você tem um ponto.",
  ui_story_5015_50150101_225_dialog_content = "Mas não acho que foi isso que o Mordomo lhe disse.",
  ui_story_5015_50150101_226_dialog_content = "Ele queria que você soubesse que Lumopolis está maravilhada com a tecnologia antiga...",
  ui_story_5015_50150101_227_dialog_content = "E a Illumina se esforça para escavar e modificar ruínas antigas...",
  ui_story_5015_50150101_228_dialog_content = "Mas esta é a nossa casa, e eles vão respeitar a nossa decisão! Você, Siobhan e Florine?",
  ui_story_5015_50150101_229_dialog_content = "Absolutamente. Eu devo assumir a responsabilidade de chegar onde estamos agora...",
  ui_story_5015_50150101_230_dialog_content = "Não vou discutir ou refutar o que o Mordomo disse sobre nós.",
  ui_story_5015_50150101_231_dialog_content = "Não acredito que disse tudo para inspirar ódio em Gretel...",
  ui_story_5015_50150101_232_dialog_content = "Estava fornecendo conhecimento para Gretel.",
  ui_story_5015_50150101_233_dialog_content = "Gretel, estou certo?",
  ui_story_5015_50150101_234_dialog_content = "...",
  ui_story_5015_50150101_235_dialog_content = "Gretel, tenho estado a observá-los todo este tempo.",
  ui_story_5015_50150101_236_dialog_content = "Eles não são os inimigos que pensávamos que fossem.",
  ui_story_5015_50150101_237_dialog_content = "Alguns deles vieram da terra natal de nossos pais e querem que tenhamos uma vida melhor.",
  ui_story_5015_50150101_238_dialog_content = "Alguns outros estão dispostos a nos dar uma mão.",
  ui_story_5015_50150101_239_dialog_content = "Eles passaram no meu teste. Eu não vou deixar ninguém te machucar.",
  ui_story_5015_50150101_240_dialog_content = "E nunca abandonarei Butler ou nossa casa.",
  ui_story_5015_50150101_241_dialog_content = "Confie em mim, você faria?",
  ui_story_5015_50150101_242_dialog_content = "...",
  ui_story_5015_50150201_1_dialog_content = "Confie em mim, você faria?",
  ui_story_5015_50150201_2_dialog_content = "...",
  ui_story_5015_50150201_3_dialog_content = "... Mas eles feriram Butler antes.",
  ui_story_5015_50150201_4_dialog_content = "Peço desculpas por nosso ataque anterior ao mordomo, Gretel. Agimos puramente por impulso.",
  ui_story_5015_50150201_5_dialog_content = "Eles tiveram algum mal-entendido sobre isso. Estou certo, Erica e Florine?",
  ui_story_5015_50150201_6_dialog_content = "Err... eu estava muito assustado e preocupado com esse poder de um mundo desconhecido...",
  ui_story_5015_50150201_7_dialog_content = "*Tosse*... Erica... Devemos admitir nossos erros agora.",
  ui_story_5015_50150201_8_dialog_content = "Sim, presidente... Desculpe, Gretel. Eu agi no calor do momento...",
  ui_story_5015_50150201_9_dialog_content = "Prometo que não iniciarei outro ataque tão precipitadamente.",
  ui_story_5015_50150201_10_dialog_content = "Você é um filho do Deus da Luz assim como eu. Não devemos machucar uns aos outros.",
  ui_story_5015_50150201_11_dialog_content = "Lumopolis e nossas doutrinas nos ensinam a amar os filhos do Deus da Luz...",
  ui_story_5015_50150201_12_dialog_content = "... E protegê-lo.",
  ui_story_5015_50150201_13_dialog_content = "Vamos destruir aqueles prejudiciais para você.",
  ui_story_5015_50150201_14_dialog_content = "Com base em nossas experiências anteriores, assumimos que a IA poderia prejudicá-lo, então atacamos precipitadamente.",
  ui_story_5015_50150201_15_dialog_content = "Se o Mordomo não te machucar, nós não o machucaremos.",
  ui_story_5015_50150201_16_dialog_content = "Butler nunca vai me machucar...",
  ui_story_5015_50150201_17_dialog_content = "Você pode realmente assumir seus erros e corrigi-los depois de causar tanta destruição?",
  ui_story_5015_50150201_18_dialog_content = "Podemos! Não causaremos mais danos à vontade.",
  ui_story_5015_50150201_19_dialog_content = "Hmm... E aquele ladrão?",
  ui_story_5015_50150201_20_dialog_content = "Hã? Eu?",
  ui_story_5015_50150201_21_dialog_content = "Multar. Eu estava errado. Peço desculpas...",
  ui_story_5015_50150201_22_dialog_content = "Veja, eu peguei apenas algumas coisas do lado da rua. Eu não sabia que alguém iria querer isso.",
  ui_story_5015_50150201_23_dialog_content = "Hmm... Essas peças novas. Coloque-os para baixo. Você não pode levá-los.",
  ui_story_5015_50150201_24_dialog_content = "Multar. Eu os coloquei para baixo...",
  ui_story_5015_50150201_25_dialog_content = "O que mais você tomou? Entregue-os.",
  ui_story_5015_50150201_26_dialog_content = "Gretel, permito que Siobhan pegue o diário do papai.",
  ui_story_5015_50150201_27_dialog_content = "Que? Que...",
  ui_story_5015_50150201_28_dialog_content = "Papai queria assim. Foi em suas últimas palavras.",
  ui_story_5015_50150201_29_dialog_content = "Sério? Mas por que...",
  ui_story_5015_50150201_30_dialog_content = "sim. Eu adoraria ler a última carta do seu pai, mas não temos tempo para isso agora.",
  ui_story_5015_50150201_31_dialog_content = "A cidade está em perigo...",
  ui_story_5015_50150201_32_dialog_content = "Vamos encontrar Butler e conversar mais no caminho?",
  ui_story_5015_50150201_33_dialog_content = "Irmã, você quer dizer que eles estão vindo conosco?",
  ui_story_5015_50150201_34_dialog_content = "Sim, eles podem ser úteis.",
  ui_story_5015_50150201_35_dialog_content = "Útil?",
  ui_story_5015_50150201_36_dialog_content = "Está certo. Agora sou um amigo da cidade. Eu farei o meu melhor para ajudar.",
  ui_story_5015_50150201_37_dialog_content = "O Mordomo me disse que isso elevava nossa permissão. Eu sou um amigo, e você agora é um residente da cidade.",
  ui_story_5015_50150201_38_dialog_content = "O Mordomo precisava de sua ajuda para controlar o núcleo de energia. Está muito preocupado com um módulo chamado Abby.",
  ui_story_5015_50150201_39_dialog_content = "Butler te disse isso? Isto é impossível. Ele é...",
  ui_story_5015_50150201_40_dialog_content = "Eu estou dizendo a verdade. Eu sou um celestita.",
  ui_story_5015_50150201_41_dialog_content = "A raça Caelestite pode estabelecer uma conexão telepática com a IA.",
  ui_story_5015_50150201_42_dialog_content = "Papai mencionou que... Os celestitas podem fazer isso...",
  ui_story_5015_50150201_43_dialog_content = "Vou ajudar o mordomo. Todos nós somos.",
  ui_story_5015_50150201_44_dialog_content = "Sério?",
  ui_story_5015_50150201_45_dialog_content = "Não, preciso verificar isso com Butler... Não posso simplesmente aceitar suas palavras.",
  ui_story_5015_50150201_46_dialog_content = "Sem problemas. Fale com ele.",
  ui_story_5015_50150201_47_dialog_content = "Não posso alcançá-lo no momento. Ele me deu uma localizaçăo... Eu o encontrarei lá.",
  ui_story_5015_50150201_48_dialog_content = "Por favor, podemos ir junto?",
  ui_story_5015_50150201_49_dialog_content = "Butler desapareceu no meio da nossa conversa. Estou preocupado com ele.",
  ui_story_5015_50150201_50_dialog_content = "Ele desapareceu? O terremoto mais cedo...",
  ui_story_5015_50150201_51_dialog_content = "Gretel, precisamos encontrar o mordomo e confirmar sua segurança!",
  ui_story_5015_50150201_52_dialog_content = "Hmm, certo. O mordomo é o mais importante...",
  ui_story_5015_50150201_53_dialog_content = "Eu sei onde ele está. Vamos encontrá-lo!",
  ui_story_5015_50150201_54_dialog_content = "Ainda não está lá? Os caminhos aqui embaixo são muito complexos...",
  ui_story_5015_50150201_55_dialog_content = "Não se preocupe. A direção de Butler deve estar certa.",
  ui_story_5015_50150201_56_dialog_content = "Irmã, você é muito paciente com essas pessoas. Devíamos costurar os lábios deles.",
  ui_story_5015_50150201_57_dialog_content = "Eu nunca serei seu guia se não fosse pelo Mordomo e sua irmã!",
  ui_story_5015_50150201_58_dialog_content = "Rouge, olha! Eu peguei isso de uma máquina que acabamos de passar.",
  ui_story_5015_50150201_59_dialog_content = "É um tubo de brilho usando alguma tecnologia de exibição de baixo desempenho.",
  ui_story_5015_50150201_60_dialog_content = "Vocês dois começaram de novo?",
  ui_story_5015_50150201_61_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5015_50150201_62_dialog_content = "Ruby, coloque de volta.",
  ui_story_5015_50150201_63_dialog_content = "Multar. Eu coloquei de volta... Não fique fisicamente. Relaxar...",
  ui_story_5015_50150201_64_dialog_content = "Hunf.",
  ui_story_5015_50150201_65_dialog_content = "Se você estiver interessado em pequenas coisas bonitas, eu posso te presentear com algumas assim que sairmos. Lindas e valiosas.",
  ui_story_5015_50150201_66_dialog_content = "Negócio!",
  ui_story_5015_50150201_67_dialog_content = "Ei, vocês são exploradores.",
  ui_story_5015_50150201_68_dialog_content = "Há mais coisas para buscar além dessas bugigangas cintilantes.",
  ui_story_5015_50150201_69_dialog_content = "Por que existem instalações vivas? Aqueles humanos antigos não viviam no andar de cima?",
  ui_story_5015_50150201_70_dialog_content = "Isso é bastante comum.",
  ui_story_5015_50150201_71_dialog_content = "Um ecossistema tão complexo exigiria muitos cientistas e técnicos para gerenciar e manter.",
  ui_story_5015_50150201_72_dialog_content = "Eles ficariam aqui a maior parte do tempo.",
  ui_story_5015_50150201_73_dialog_content = "Também poderia ser uma medida para lidar com os riscos.",
  ui_story_5015_50150201_74_dialog_content = "Como quando a IA fica fora de controle, certo?",
  ui_story_5015_50150201_75_dialog_content = "Mesmo aqueles humanos antigos sabiam que as máquinas não eram totalmente confiáveis. Um dia eles podem assumir.",
  ui_story_5015_50150201_76_dialog_content = "Que? Sério?",
  ui_story_5015_50150201_77_dialog_content = "Aconteceu de acordo com alguns documentos antigos.",
  ui_story_5015_50150201_78_dialog_content = "Em resposta, os humanos antigos inventaram muitas novas tecnologias, como um sistema de gerenciamento de permissões de vários níveis.",
  ui_story_5015_50150201_79_dialog_content = "Por favor, não me dê esses termos técnicos...",
  ui_story_5015_50150201_80_dialog_content = "Tantas máquinas chatas! As pessoas que moram aqui devem ser menos felizes do que as que moram lá em cima!",
  ui_story_5015_50150201_81_dialog_content = "É o mesmo em Gannon. As pessoas que mantêm a cidade funcionando passam a maior parte do tempo trabalhando e vivendo nas profundezas do solo.",
  ui_story_5015_50150201_82_dialog_content = "Sem eles, como a Illumina pode operar sem problemas?",
  ui_story_5015_50150201_83_dialog_content = "No entanto, muitos dos antigos que vivem na falsa metrópole lá em cima...",
  ui_story_5015_50150201_84_dialog_content = "Receio que eles nem sabiam que estavam em uma cidade subterrânea.",
  ui_story_5015_50150201_85_dialog_content = "Sim. Por que eles se preocuparam em colocar um céu falso lá em cima?",
  ui_story_5015_50150201_86_dialog_content = "Talvez os designers deste lugar quisessem que seus filhos se lembrassem de como é o mundo exterior.",
  ui_story_5015_50150201_87_dialog_content = "Sabendo que você está preso para a vida no subsolo...",
  ui_story_5015_50150201_88_dialog_content = "Pode ser terrível para muitos. Os humanos não podem viver sem esperança.",
  ui_story_5015_50150201_89_dialog_content = "A última vez que um grupo de investigação nosso descobriu uma antiga cidade subterrânea...",
  ui_story_5015_50150201_90_dialog_content = "Foi destruído durante uma batalha feroz entre povos antigos e máquinas.",
  ui_story_5015_50150201_91_dialog_content = "Gretel, você vê. As pessoas de Lumopolis são impulsivas porque viram esses casos.",
  ui_story_5015_50150201_92_dialog_content = "Nós não somos um desses!",
  ui_story_5015_50150201_93_dialog_content = "Eu sei. Mas eles têm medo. E o medo pode tirar o melhor de você...",
  ui_story_5015_50150201_94_dialog_content = "Siobhan, como você pôde jogar lama em nós na frente de Gretel?",
  ui_story_5015_50150201_95_dialog_content = "Eu estava simplesmente dando uma explicação para seu comportamento anterior.",
  ui_story_5015_50150201_96_dialog_content = "Não há necessidade. Eu te perdôo por agora... Só por agora. Atreva-se a fazer isso de novo...",
  ui_story_5015_50150201_97_dialog_content = "Ai. Não ousamos!",
  ui_story_5015_50150201_98_dialog_content = "Valencia e Gretel, já viram o mordomo antes?",
  ui_story_5015_50150201_99_dialog_content = "Claro. Você não tem?",
  ui_story_5015_50150201_100_dialog_content = "Siobhan está perguntando sobre o verdadeiro Butler. Aquele dróide é mais como um megafone.",
  ui_story_5015_50150201_101_dialog_content = "Do que você está falando?",
  ui_story_5015_50150201_102_dialog_content = "A IA geralmente vem com um complicado sistema de processamento e sistema de dados.",
  ui_story_5015_50150201_103_dialog_content = "Um pequeno droide não aguenta tudo isso. Seu Butler é mais como um terminal de um módulo maior.",
  ui_story_5015_50150201_104_dialog_content = "Como Soroz?",
  ui_story_5015_50150201_105_dialog_content = "Deixe-me colocar deste jeito. Se compararmos a IA a uma alma...",
  ui_story_5015_50150201_106_dialog_content = "O corpo que o contém pode ser centenas de milhares de vezes maior que um auroriano.",
  ui_story_5015_50150201_107_dialog_content = "Senhorita Florine, como você sabe disso?",
  ui_story_5015_50150201_108_dialog_content = "Presidente, o que você está dizendo?",
  ui_story_5015_50150201_109_dialog_content = "Erica, você saberia disso se levasse o curso Tech Magic mais a sério...",
  ui_story_5015_50150201_110_dialog_content = "Eu pensei que era apenas uma piada que todos os membros da Divisão de Investigação de Hereges deveriam tomar a Illumina Tech.",
  ui_story_5015_50150201_111_dialog_content = "Senhorita Florine, por que não se juntar a nós e se tornar uma cientista?",
  ui_story_5015_50150201_112_dialog_content = "Certo. Um dos lugares que estou morrendo de vontade de ver é o laboratório secreto no Illumina Research Center.",
  ui_story_5015_50150201_113_dialog_content = "Deixa pra lá. Esqueça isso. Receio que possa roubar todos os nossos segredos.",
  ui_story_5015_50150201_114_dialog_content = "Hunf.",
  ui_story_5015_50150201_115_dialog_content = "Florine, você poderia nos contar mais sobre nossa cidade e o Mordomo? Papai raramente mencionava isso...",
  ui_story_5015_50150201_116_dialog_content = "só sei o básico...",
  ui_story_5015_50150201_117_dialog_content = "Você precisa perguntar à senhorita Siobhan, a pesquisadora científica especializada em tecnologia antiga.",
  ui_story_5015_50150201_118_dialog_content = "Para simplificar, há muito tempo, humanos antigos construíram muitos abrigos subterrâneos na esperança de sobreviver a terríveis devastações.",
  ui_story_5015_50150201_119_dialog_content = "Para durar longos anos, a maioria desses abrigos subterrâneos foi equipada com energia, droides e gerenciamento de IA.",
  ui_story_5015_50150201_120_dialog_content = "A IA pode ser classificada em vários tipos. Estamos estudando isso há anos, mas o progresso é pequeno.",
  ui_story_5015_50150201_121_dialog_content = "Ou você está apenas se segurando porque eu estou aqui?",
  ui_story_5015_50150201_122_dialog_content = "... De qualquer forma, tenho muita certeza de que o Butler é um sistema composto por um conjunto completo de máquinas complicadas e enormes.",
  ui_story_5015_50150201_123_dialog_content = "Como Butler controla e comanda droides?",
  ui_story_5015_50150201_124_dialog_content = "É bastante semelhante ao nosso conceito de terminais.",
  ui_story_5015_50150201_125_dialog_content = "No entanto, a tecnologia antiga empregava um tipo de onda completamente diferente do nosso. Eles são até mutuamente exclusivos às vezes.",
  ui_story_5015_50150201_126_dialog_content = "Os humanos antigos previram isso.",
  ui_story_5015_50150201_127_dialog_content = "Como resultado, uma cidade subterrânea normalmente apresentaria um sistema de barreira para garantir a transmissão de informações usando suas ondas.",
  ui_story_5015_50150201_128_dialog_content = "Você me perdeu.",
  ui_story_5015_50150201_129_dialog_content = "Digamos que humanos antigos tenham seus próprios terminais para enviar comandos para seus droides, e eles são capazes de bloquear nossos terminais.",
  ui_story_5015_50150201_130_dialog_content = "Isso poderia explicar como o sinal de resgate de Seamus saiu durante um terremoto...",
  ui_story_5015_50150201_131_dialog_content = "Sim, o terremoto afetou as operações da cidade subterrânea, então talvez a rede de interferência tenha sido temporariamente desativada.",
  ui_story_5015_50150201_132_dialog_content = "Na verdade, estou mais preocupado que nossos camaradas Illumina venham aqui e também fiquem presos depois de receber nosso sinal de socorro...",
  ui_story_5015_50150201_133_dialog_content = "Siobhan, muitas coisas que você disse soam como o que o pai costumava dizer.",
  ui_story_5015_50150201_134_dialog_content = "Ah...",
  ui_story_5015_50150201_135_dialog_content = "Quanto tempo mais temos que continuar andando? Eu estou morrendo de tédio.",
  ui_story_5015_50150201_136_dialog_content = "Ruby, você não vê como é excitante aqui?",
  ui_story_5015_50150201_137_dialog_content = "Emocionante? Eu sinto tanta falta dos andares superiores agora.",
  ui_story_5015_50150201_138_dialog_content = "Todo o ecossistema, o sistema automático de plantio e cultivo, assim como todos os equipamentos automatizados da cidade alta, contam com este local.",
  ui_story_5015_50150201_139_dialog_content = "Este sistema complexo permitiu que eles funcionassem perfeitamente por incontáveis anos.",
  ui_story_5015_50150201_140_dialog_content = "Tudo aqui é um milagre.",
  ui_story_5015_50150201_141_dialog_content = "Não sei como os povos antigos faziam isso, mas temo que precisaremos de centenas de anos para estudar todo o equipamento aqui.",
  ui_story_5015_50150201_142_dialog_content = "O que vem depois disso? O que você quer fazer?",
  ui_story_5015_50150201_143_dialog_content = "Os debates olho por olho entre Illumina e Lumopolis são mais irritantes do que os Eclipsites.",
  ui_story_5015_50150201_144_dialog_content = "Um de vocês quer ser um herói e o outro quer ser um santo.",
  ui_story_5015_50150201_145_dialog_content = "Não podemos deixar que todos escolham por si mesmos?",
  ui_story_5015_50150201_146_dialog_content = "Apenas use tecnologia antiga se você gostar, e não use se você não quiser. Não é tão simples assim?",
  ui_story_5015_50150201_147_dialog_content = "Haha, se as coisas fossem tão simples assim.",
  ui_story_5015_50150201_148_dialog_content = "<color=#e8d9bb>Bip Bip...</color>",
  ui_story_5015_50150201_149_dialog_content = "Cuidado, um droid está chegando!",
  ui_story_5015_50150201_150_dialog_content = "Não se preocupe, eles não vão nos atacar.",
  ui_story_5015_50150201_151_dialog_content = "Como Gretel os controla?",
  ui_story_5015_50150201_152_dialog_content = "Eu não sei, eles apenas fazem o que eu digo.",
  ui_story_5015_50150201_153_dialog_content = "O Mordomo disse que você é um \"residente\", Valencia e eu somos \"amigos\" e todos os outros são \"não hostis\".",
  ui_story_5015_50150201_154_dialog_content = "Acho que os moradores têm o direito de comandar os droides.",
  ui_story_5015_50150201_155_dialog_content = "É por isso que Valência e PlayerName não tem poder.",
  ui_story_5015_50150201_156_dialog_content = "Não é difícil notar um padrão se você revisar todas as batalhas que tivemos desde que chegamos aqui.",
  ui_story_5015_50150201_157_dialog_content = "Os Eclipsites não atacam residentes, como Gretel agora.",
  ui_story_5015_50150201_158_dialog_content = "Mas eles ainda atacam amigos e não hostis.",
  ui_story_5015_50150201_159_dialog_content = "Os droides não atacarão alvos que não sejam inimigos, incluindo Eclipsites.",
  ui_story_5015_50150201_160_dialog_content = "Mas se os Eclipsites atacarem amigos, os droides os protegerão.",
  ui_story_5015_50150201_161_dialog_content = "A família Seamus é protegida pelos droides como amigos.",
  ui_story_5015_50150201_162_dialog_content = "Claro, quem atacar os droides ou destruir a cidade se tornará inimigo.",
  ui_story_5015_50150201_163_dialog_content = "Quem estabeleceu essas regras?",
  ui_story_5015_50150201_164_dialog_content = "Eles poderiam ter sido criados pelos povos antigos, ou poderiam ter sido criados pela Supermente...",
  ui_story_5015_50150201_165_dialog_content = "Também pode ser uma falha do sistema. De qualquer forma, vamos encontrar o mordomo primeiro.",
  ui_story_5015_50150201_166_dialog_content = "A única coisa que não entendo é por que até os Eclipsitas seguem essas regras e atacam os inimigos...",
  ui_story_5015_50150201_167_dialog_content = "O fato de os Eclipsitas não atacarem os moradores deve ser suficiente para provar que eles estão relacionados de alguma forma com esta cidade, certo?",
  ui_story_5015_50150201_168_dialog_content = "Sim, o Eclipsite segue as regras e é capaz de perceber rapidamente quando o status de uma pessoa muda.",
  ui_story_5015_50150201_169_dialog_content = "Assim como os dróides.",
  ui_story_5015_50150201_170_dialog_content = "Eu acho que os Eclipses aqui são bem especiais.",
  ui_story_5015_50150201_171_dialog_content = "Grrr...",
  ui_story_5015_50150201_172_dialog_content = "É um ataque Eclipsite!",
  ui_story_5015_50150201_173_dialog_content = "Chega de falar. É hora de lutar!",
  ui_story_5015_50150201_174_dialog_content = "Gretel, você pode fazer os Eclipsites parar?",
  ui_story_5015_50150201_175_dialog_content = "Eu... eu não posso!",
  ui_story_5015_50150201_176_dialog_content = "Os dróides realmente vieram para ajudar.",
  ui_story_5015_50150201_177_dialog_content = "Vê isto! Cobrar!",
  ui_story_5015_50150201_178_dialog_content = "Por que parece que os Eclipsites são mais fortes desta vez?",
  ui_story_5015_50150201_179_dialog_content = "Eu tenho o mesmo sentimento. Os Eclipsites que encontramos aqui ficam cada vez mais fortes.",
  ui_story_5015_50150201_180_dialog_content = "Ambos os droides e Eclipsites estão ficando mais fortes. Isso não significa que estamos ficando mais fracos?",
  ui_story_5015_50150201_181_dialog_content = "Os droides estão ficando mais fortes porque o Mordomo continua analisando nossas batalhas e aprimorando seus designs.",
  ui_story_5015_50150201_182_dialog_content = "O Eclipsite também pode revisar suas batalhas e mudar?",
  ui_story_5015_50150201_183_dialog_content = "Eu folheei as notas de pesquisa de Seamus.",
  ui_story_5015_50150201_184_dialog_content = "Ele sempre suspeitou que os Eclipsitas da cidade foram feitos por alguém. Ele até suspeitava do Mordomo...",
  ui_story_5015_50150201_185_dialog_content = "I-isso é impossível!",
  ui_story_5015_50150201_186_dialog_content = "Se ele realmente queria nos prejudicar, então por que ele nos salvaria?",
  ui_story_5015_50150201_187_dialog_content = "Não, é precisamente isso que torna a inteligência artificial perigosa.",
  ui_story_5015_50150201_188_dialog_content = "Se a inteligência artificial achar necessário estudar Luminatics ou qualquer outra coisa...",
  ui_story_5015_50150201_189_dialog_content = "A possibilidade de fazer os Eclipsites atacarem sua família não pode ser descartada.",
  ui_story_5015_50150201_190_dialog_content = "Eu até encontrei alguma inteligência artificial que acreditava que uma grande população de pessoas antigas colocaria em risco a segurança da cidade subterrânea...",
  ui_story_5015_50150201_191_dialog_content = "... e mataram todos para resolver o problema.",
  ui_story_5015_50150201_192_dialog_content = "Você está se referindo ao R - Ruins de três anos atrás, certo?",
  ui_story_5015_50150201_193_dialog_content = "Sim, embora tenhamos conseguido apenas pedaços de informação, a Srta. Hedy ainda conseguiu decifrar muitas informações preciosas.",
  ui_story_5015_50150201_194_dialog_content = "E então você usou essa informação para encontrar a parte central do R - Ruins antes de nós.",
  ui_story_5015_50150201_195_dialog_content = "Sim, nós o encontramos e até o vasculhamos em grande detalhe.",
  ui_story_5015_50150201_196_dialog_content = "Tenho certeza que também estaremos à frente desta vez...",
  ui_story_5015_50150201_197_dialog_content = "Você não deveria dizer esse tipo de coisa com frequência.",
  ui_story_5015_50150201_198_dialog_content = "Com base no que você disse, o Mordomo parece...",
  ui_story_5015_50150201_199_dialog_content = "Não, o Butler não vai.",
  ui_story_5015_50150201_200_dialog_content = "Depois de dizer tudo isso, você já pensou em...",
  ui_story_5015_50150201_201_dialog_content = "Se você quer destruir ou tomar este lugar, ainda precisamos sair primeiro, certo?",
  ui_story_5015_50150201_202_dialog_content = "Florine, se você realmente destruir este lugar, seremos enterrados junto com esta cidade subterrânea.",
  ui_story_5015_50150201_203_dialog_content = "Você realmente vai fazer isso?",
  ui_story_5015_50150201_204_dialog_content = "Siobhan, se você tiver menos discussões com eles...",
  ui_story_5015_50150201_205_dialog_content = "Rubi, isso é o suficiente. Entendo claramente nossa situação, e tenho certeza de que Florine também.",
  ui_story_5015_50150201_206_dialog_content = "Nossa maior prioridade é definitivamente encontrar uma saída.",
  ui_story_5015_50150201_207_dialog_content = "Então, não vamos fazer nada muito extremo. Você concorda comigo, Srta. Florine?",
  ui_story_5015_50150201_208_dialog_content = "Sim eu concordo.",
  ui_story_5015_50150201_209_dialog_content = "O que devemos fazer se o Mordomo realmente adormeceu?",
  ui_story_5015_50150201_210_dialog_content = "Há tantos de nós... Tenho certeza que encontraremos um jeito.",
  ui_story_5015_50150201_211_dialog_content = "Sempre podemos voltar aos andares superiores e continuar a pesquisa de Seamus. Eventualmente encontraremos a saída.",
  ui_story_5015_50150201_212_dialog_content = "Se houver mais terremotos, este lugar será destruído antes de encontrar uma saída.",
  ui_story_5015_50150201_213_dialog_content = "Ainda mais um motivo para voltar aos andares superiores. Pelo menos há roupas bonitas, comida saborosa e belas paisagens por lá.",
  ui_story_5015_50150201_214_dialog_content = "Você não quer ficar aqui de jeito nenhum? O mundo exterior é tão bom assim?",
  ui_story_5015_50150201_215_dialog_content = "Você saberá quando experimentar por si mesmo.",
  ui_story_5015_50150201_216_dialog_content = "A localização que o mordomo me deu deve estar à frente.",
  ui_story_5015_50150201_217_dialog_content = "Finalmente...",
  ui_story_5015_50150201_218_dialog_content = "Ah não! Há Eclipses por aqui!",
  ui_story_5015_50150201_219_dialog_content = "Preparem-se para lutar!",
  ui_story_5015_50150201_220_dialog_content = "É... É possível que os Eclipsitas ataquem o Mordomo?",
  ui_story_5015_50150201_221_dialog_content = "Isso é impossível, já que os Eclipsitas e os droides não se atacam ativamente. Estou certo, Valência?",
  ui_story_5015_50150201_222_dialog_content = "Sim, nunca vi isso acontecer antes.",
  ui_story_5015_50150201_223_dialog_content = "Vocês não podem parar de conversar antes de uma luta?",
  ui_story_5015_50150201_224_dialog_content = "Eu sou o primeiro de novo! Cobrar!",
  ui_story_5015_50150201_225_dialog_content = "Parece que estão recuando...",
  ui_story_5015_50150201_226_dialog_content = "Finalmente...",
  ui_story_5015_50150201_227_dialog_content = "Finalmente nos reencontramos...",
  ui_story_5015_50150301_1_dialog_content = "<color=#e8d9bb>Gretel, Valência, PlayerName, Olá.</color>",
  ui_story_5015_50150301_2_dialog_content = "Por que não conseguimos entrar em contato com você? Pensávamos que você fosse...",
  ui_story_5015_50150301_3_dialog_content = "<color=#e8d9bb>Estou bem... só preciso... de tempo... para me recuperar... Você está bem?</color>",
  ui_story_5015_50150301_4_dialog_content = "Encontrei-os a caminho do núcleo de energia... Minha irmã não me deixou ir.",
  ui_story_5015_50150301_5_dialog_content = "Butler, você realmente acha certo pedir a Gretel para fazer algo tão perigoso?",
  ui_story_5015_50150301_6_dialog_content = "<color=#e8d9bb>Se o terremoto... Se o núcleo... for danificado, as coisas ficarão muito ruins.</color>",
  ui_story_5015_50150301_7_dialog_content = "Essa pessoa disse que é seu amigo. Isso é verdade?",
  ui_story_5015_50150301_8_dialog_content = "<color=#e8d9bb>Sim... PlayerName é um celestita, amigo da cidade.</color>",
  ui_story_5015_50150301_9_dialog_content = "Butler, nos encontramos novamente.",
  ui_story_5015_50150301_10_dialog_content = "<color=#e8d9bb>Saudações, Celestita.</color>",
  ui_story_5015_50150301_11_dialog_content = "As máquinas atrás de você são o verdadeiro você, certo?",
  ui_story_5015_50150301_12_dialog_content = "Ei, vamos acabar com as formalidades e ir direto ao ponto. Eu vou falar!",
  ui_story_5015_50150301_13_dialog_content = "Butler, só queremos sair daqui agora. Onde está a saída?",
  ui_story_5015_50150301_14_dialog_content = "...",
  ui_story_5015_50150301_15_dialog_content = "<color=#e8d9bb>Desculpe, permissão negada. Eu não posso responder a esta pergunta.</color>",
  ui_story_5015_50150301_16_dialog_content = "Vou perguntar então. Butler, como podemos deixar este lugar?",
  ui_story_5015_50150301_17_dialog_content = "<color=#e8d9bb>Eu não tenho nenhuma... informação sobre como sair da cidade.</color>",
  ui_story_5015_50150301_18_dialog_content = "Onde podemos descobrir?",
  ui_story_5015_50150301_19_dialog_content = "<color=#e8d9bb>Desculpe... Permissão negada... Não posso responder a esta pergunta.</color>",
  ui_story_5015_50150301_20_dialog_content = "Butler, o que você precisa que façamos?",
  ui_story_5015_50150301_21_dialog_content = "<color=#e8d9bb>Você pode viver... com segurança... na cidade...</color>",
  ui_story_5015_50150301_22_dialog_content = "<color=#e8d9bb>Mas lembre-se de seguir as regras... Não coloque em risco a segurança da cidade.</color>",
  ui_story_5015_50150301_23_dialog_content = "Só descobri hoje que os Eclipsitas não atacam moradores.",
  ui_story_5015_50150301_24_dialog_content = "Butler, por que você não deixou mamãe e papai se tornarem residentes?",
  ui_story_5015_50150301_25_dialog_content = "Se você os deixasse, eles não teriam morrido!",
  ui_story_5015_50150301_26_dialog_content = "Irmã...",
  ui_story_5015_50150301_27_dialog_content = "<color=#e8d9bb>Valencia, não estabeleci os critérios de aprovação para os residentes.</color>",
  ui_story_5015_50150301_28_dialog_content = "<color=#e8d9bb>Devo insistir... De acordo com os cálculos... A tarefa mais importante é reparar o núcleo de energia.</color>",
  ui_story_5015_50150301_29_dialog_content = "<color=#e8d9bb>Se não for reparado, a cidade pode desmoronar completamente em menos de 100 tremores secundários.</color>",
  ui_story_5015_50150301_30_dialog_content = "Esqueça. Vamos parar de jogar esse jogo de adivinhação e apenas procurar as informações.",
  ui_story_5015_50150301_31_dialog_content = "Pena que não entendo muito de inteligência artificial...",
  ui_story_5015_50150301_32_dialog_content = "PlayerName, o que você pode sentir das máquinas do mordomo?",
  ui_story_5015_50150301_33_dialog_content = "Não, eu não podia sentir nada.",
  ui_story_5015_50150301_34_dialog_content = "Espere, eu posso sentir Eclipsites!",
  ui_story_5015_50150301_35_dialog_content = "Por que existem tantos Eclipsites?!",
  ui_story_5015_50150301_36_dialog_content = "Florine, venha comigo para atrair a atenção dos Eclipsitas de lado.",
  ui_story_5015_50150301_37_dialog_content = "Ruby, você lidera os outros e se prepara para romper.",
  ui_story_5015_50150301_38_dialog_content = "Atenção! Gretel!",
  ui_story_5015_50150301_39_dialog_content = "Os Eclipsites estão realmente atacando Gretel??",
  ui_story_5015_50150301_40_dialog_content = "Valencia, Gretel, venham até mim.",
  ui_story_5015_50150301_41_dialog_content = "Não se preocupe, estou bem, Valencia.",
  ui_story_5015_50150301_42_dialog_content = "Vou pedir aos droides para ajudá-la, Ruby.",
  ui_story_5015_50150301_43_dialog_content = "Surpreendente!",
  ui_story_5015_50150301_44_dialog_content = "Os Eclipsitas estão recuando!",
  ui_story_5015_50150301_45_dialog_content = "Butler, por que os Eclipsites estão atacando Gretel?",
  ui_story_5015_50150301_46_dialog_content = "Você privou o status de Gretel como residente dela?",
  ui_story_5015_50150301_47_dialog_content = "<color=#e8d9bb>Não, eu não fiz.</color>",
  ui_story_5015_50150301_48_dialog_content = "Seu mentiroso!",
  ui_story_5015_50150301_49_dialog_content = "PlayerName, eu não acho que está mentindo.",
  ui_story_5015_50150301_50_dialog_content = "Gretel ainda pode ordenar que os droides lutem, então ela ainda é uma residente.",
  ui_story_5015_50150301_51_dialog_content = "E os dróides não estão nos atacando.",
  ui_story_5015_50150301_52_dialog_content = "Então, não nos tornamos inimigos da cidade. Estou certo, Butler?",
  ui_story_5015_50150301_53_dialog_content = "<color=#e8d9bb>Eu não conto mentiras.</color>",
  ui_story_5015_50150301_54_dialog_content = "De qualquer forma, agora que os Eclipsites começaram a atacar os moradores, isso significa que se tornou ainda mais perigoso?",
  ui_story_5015_50150301_55_dialog_content = "<color=#e8d9bb>De acordo com meus cálculos... Se eu não te der informações relevantes...</color>",
  ui_story_5015_50150301_56_dialog_content = "<color=#e8d9bb>Você realmente estará em maior perigo.</color>",
  ui_story_5015_50150301_57_dialog_content = "<color=#e8d9bb>Vou tentar dizer-lhe de uma forma que você possa... entender.</color>",
  ui_story_5015_50150301_58_dialog_content = "<color=#e8d9bb>Os Eclipsitas foram de fato feitos por esta cidade... Só recentemente verifiquei isso completamente.</color>",
  ui_story_5015_50150301_59_dialog_content = "<color=#e8d9bb>Depois que acordei... Percebi que todos os moradores desapareceram.</color>",
  ui_story_5015_50150301_60_dialog_content = "<color=#e8d9bb>E havia uma nova espécie estrangeira na cidade... os Eclipsitas.</color>",
  ui_story_5015_50150301_61_dialog_content = "<color=#e8d9bb>Eu não sabia... o que aconteceu.</color>",
  ui_story_5015_50150301_62_dialog_content = "<color=#e8d9bb>Mas de acordo com algumas informações, os Eclipsitas atacaram os moradores... resultando em sua eliminação.</color>",
  ui_story_5015_50150301_63_dialog_content = "Achei que havia uma falha no sistema de gestão da cidade... levou os Eclipsitas a romper a barreira e invadir este lugar.",
  ui_story_5015_50150301_64_dialog_content = "Os povos antigos que não eram protegidos pelos droides eram...",
  ui_story_5015_50150301_65_dialog_content = "<color=#e8d9bb>Existe essa possibilidade... mas não encontrei nenhuma informação.</color>",
  ui_story_5015_50150301_66_dialog_content = "<color=#e8d9bb>Sempre que pretendo procurar a origem dos Eclipsitos... não consigo prosseguir porque não tenho a autorização necessária.</color>",
  ui_story_5015_50150301_67_dialog_content = "<color=#e8d9bb>Sempre esperei que outros módulos despertassem.</color>",
  ui_story_5015_50150301_68_dialog_content = "<color=#e8d9bb>Abby que tem mais conhecimento biológico... Hughes, que está no comando do sistema de combate, ou mesmo...</color>",
  ui_story_5015_50150301_69_dialog_content = "<color=#e8d9bb>Depois disso, Seamus e os outros vieram.</color>",
  ui_story_5015_50150301_70_dialog_content = "<color=#e8d9bb>Percebi que o comportamento dos Eclipsites... seguia uma lógica semelhante à dos droides.</color>",
  ui_story_5015_50150301_71_dialog_content = "Eu sei, por que você não tenta marcar os Eclipsitas como inimigos da cidade?",
  ui_story_5015_50150301_72_dialog_content = "<color=#e8d9bb>De acordo com meus cálculos... Se os Eclipsitas estão marcados como inimigos.</color>",
  ui_story_5015_50150301_73_dialog_content = "<color=#e8d9bb>Mais recursos seriam usados para o combate... A longo prazo, isso seria mais perigoso para a cidade.</color>",
  ui_story_5015_50150301_74_dialog_content = "<color=#e8d9bb>Não mataremos nenhuma criatura facilmente... incluindo Aurorianos e Eclipsitas.</color>",
  ui_story_5015_50150301_75_dialog_content = "Vimos um mecanismo de proteção semelhante chamado lei em outra cidade baixa.",
  ui_story_5015_50150301_76_dialog_content = "Talvez essa fosse uma das preocupações dos povos antigos com a inteligência artificial.",
  ui_story_5015_50150301_77_dialog_content = "<color=#e8d9bb>Depois, classifiquei e analisei as informações fragmentadas...</color>",
  ui_story_5015_50150301_78_dialog_content = "<color=#e8d9bb>Percebi que o Eclipsite e os humanos antigos pareciam compartilhar muitas características semelhantes.</color>",
  ui_story_5015_50150301_79_dialog_content = "Espere o que?! Os Eclipsitas e os humanos antigos tinham muitas semelhanças?",
  ui_story_5015_50150301_80_dialog_content = "<color=#e8d9bb>Algumas características foram selecionadas de forma não natural e realizadas através da evolução.</color>",
  ui_story_5015_50150301_81_dialog_content = "<color=#e8d9bb>De acordo com os arquivos deixados pelos humanos antigos, os Eclipsitas de hoje pareciam ter passado pelo mesmo...</color>",
  ui_story_5015_50150301_82_dialog_content = "Modificação. Eles eram criaturas modificadas artificialmente.",
  ui_story_5015_50150301_83_dialog_content = "Isso torna as coisas mais simples. Abby, o módulo biológico responsável por nutrir vidas humanas...",
  ui_story_5015_50150301_84_dialog_content = "Parou ou não pôde continuar a criar humanos antigos, mas começou a desenvolver os Eclipsites.",
  ui_story_5015_50150301_85_dialog_content = "Como isso aconteceu?",
  ui_story_5015_50150301_86_dialog_content = "<color=#e8d9bb>Senhorita Siobhan, você é muito inteligente... Você me lembra Seamus.</color>",
  ui_story_5015_50150301_87_dialog_content = "Acabei de fazer uma dedução simples com base nas informações que você forneceu.",
  ui_story_5015_50150301_88_dialog_content = "Todos nós sabemos que cada cidade subterrânea tem um sistema responsável pela reprodução... Ah, Seamus provavelmente não sabia disso.",
  ui_story_5015_50150301_89_dialog_content = "Esta foi uma descoberta feita ao pesquisar outras ruínas nos últimos anos.",
  ui_story_5015_50150301_90_dialog_content = "O que significa que Seamus não teria conhecimento disso, ou então ele teria descoberto a verdade deste lugar há muito tempo.",
  ui_story_5015_50150301_91_dialog_content = "PlayerName, para evitar sua própria extinção, os humanos antigos...",
  ui_story_5015_50150301_92_dialog_content = "... eles tinham um sistema de backup responsável pela reprodução e educação em quase todos os subúrbios.",
  ui_story_5015_50150301_93_dialog_content = "Como Abby e Uma aqui.",
  ui_story_5015_50150301_94_dialog_content = "Este é o caso de Gannon e R - Ruins–",
  ui_story_5015_50150301_95_dialog_content = "No R - Ruins, também descobrimos um sistema que poderia ser usado para retornar à superfície.",
  ui_story_5015_50150301_96_dialog_content = "De acordo com as informações, isso foi usado para monitorar a ecologia da superfície e–",
  ui_story_5015_50150301_97_dialog_content = "De acordo com a ecologia da superfície...",
  ui_story_5015_50150301_98_dialog_content = "O sistema de reprodução faria com que as futuras gerações dos humanos antigos evoluíssem para se adaptar às mudanças.",
  ui_story_5015_50150301_99_dialog_content = "<color=#e8d9bb>Sim, você está certo. Myers também desapareceu...</color>",
  ui_story_5015_50150301_100_dialog_content = "Como eu esperava... Se existe um sistema que leva à superfície, então também deve haver uma passagem que leva à superfície.",
  ui_story_5015_50150301_101_dialog_content = "Devemos encontrá-lo.",
  ui_story_5015_50150301_102_dialog_content = "Se os Eclipsites continuarem evoluindo, provavelmente seremos exterminados antes que possamos encontrar a saída.",
  ui_story_5015_50150301_103_dialog_content = "Nesse caso, Butler, você pode tentar entrar em contato com Abby.",
  ui_story_5015_50150301_104_dialog_content = "O problema não será resolvido se convencermos Abby a parar com essa atividade perigosa?",
  ui_story_5015_50150301_105_dialog_content = "<color=#e8d9bb>Já lhe disse... não consigo me conectar com Abby.</color>",
  ui_story_5015_50150301_106_dialog_content = "Então você deve destruí-lo!",
  ui_story_5015_50150301_107_dialog_content = "<color=#e8d9bb>Módulos são estritamente proibidos de atacar uns aos outros.</color>",
  ui_story_5015_50150301_108_dialog_content = "...",
  ui_story_5015_50150301_109_dialog_content = "Senhorita Siobhan, a lógica do mordomo não faz mais sentido para mim.",
  ui_story_5015_50150301_110_dialog_content = "Ele experimentou o desgaste de incontáveis anos... Esqueça, talvez possamos tratar o Butler como um paciente paranóico.",
  ui_story_5015_50150301_111_dialog_content = "Suspiro, vamos procurar o sistema que pode ser usado para retornar à superfície.",
  ui_story_5015_50150301_112_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5015_50150301_113_dialog_content = "Oh não, é outro terremoto!",
  ui_story_5015_50150301_114_dialog_content = "Cuidado com a queda de objetos!",
  ui_story_5015_50150301_115_dialog_content = "Gah... Gah...!",
  ui_story_5015_50150301_116_dialog_content = "Os Eclipsites chegaram até aqui!",
  ui_story_5015_50150301_117_dialog_content = "<color=#e8d9bb>Perigo... Abby é...</color>",
  ui_story_5015_50150301_118_dialog_content = "*Rugido*",
  ui_story_5015_50150301_119_dialog_content = "O que há com esses Eclipsites? Por que eles estão cobrando sem qualquer consideração por suas vidas?",
  ui_story_5015_50150301_120_dialog_content = "Ruby, Florine, parem com esses Eclipses!",
  ui_story_5015_50150301_121_dialog_content = "Aconteceu antes, quando chegamos ao data center do Butler...",
  ui_story_5015_50150301_122_dialog_content = "Esses Eclipsitas estão tratando todos nós, incluindo o Mordomo, como seus inimigos.",
  ui_story_5015_50150301_123_dialog_content = "Eu vou dar os comandos. Acabe com eles o mais rápido possível!",
  ui_story_5015_50150301_124_dialog_content = "Grrrrr!",
  ui_story_5015_50150301_125_dialog_content = "Torrente Rápida!",
  ui_story_5015_50150301_126_dialog_content = "Deixa eu tentar!",
  ui_story_5015_50150301_127_dialog_content = "Golpe de morcego super-duper!",
  ui_story_5015_50150301_128_dialog_content = "Grrr...",
  ui_story_5015_50150301_129_dialog_content = "Finalmente acabou...",
  ui_story_5015_50150301_130_dialog_content = "Vou verificar o mordomo.",
  ui_story_5015_50150301_131_dialog_content = "<color=#e8d9bb>Não se preocupe... Eu retomei a operação normal.</color>",
  ui_story_5015_50150301_132_dialog_content = "Achei que vocês módulos não podiam atacar uns aos outros. Por que Eclipsites de Abby é...",
  ui_story_5015_50150301_133_dialog_content = "<color=#e8d9bb>Abby obteve maior... autoridade.</color>",
  ui_story_5015_50150301_134_dialog_content = "<color=#e8d9bb>Ela está conquistando ainda mais direitos de controle.</color>",
  ui_story_5015_50150301_135_dialog_content = "<color=#e8d9bb>A maioria das máquinas... estão além do meu controle agora...</color>",
  ui_story_5015_50150301_136_dialog_content = "Abby está tomando autoridade?",
  ui_story_5015_50150301_137_dialog_content = "Rouba coisas em nosso relógio...? Onde está essa Abby?!",
  ui_story_5015_50150301_138_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5015_50150301_139_dialog_content = "<color=#e8d9bb>A... é... é... é...</color>",
  ui_story_5015_50150301_140_dialog_content = "<color=#e8d9bb>Eles estão todos indo para uma direção... É onde Abby e a energia... estão.</color>",
  ui_story_5015_50150301_141_dialog_content = "Que direção é essa?",
  ui_story_5015_50150301_142_dialog_content = "O núcleo energético...",
  ui_story_5015_50150301_143_dialog_content = "<size=45><color=#FFB400>Estrelas da alquimia.</color></size>",
  ui_story_5015_50150401_1_dialog_content = "Estrelas de alquimia?",
  ui_story_5015_50150401_2_dialog_content = "<color=#e8d9bb>Este é o... nome do núcleo de energia.</color>",
  ui_story_5015_50150401_3_dialog_content = "O núcleo de energia fornece energia para toda a cidade subterrânea.",
  ui_story_5015_50150401_4_dialog_content = "Por que Abby está fazendo os droides e Eclipsites irem para lá?",
  ui_story_5015_50150401_5_dialog_content = "<color=#e8d9bb>Abby está tentando consertar o núcleo de energia.</color>",
  ui_story_5015_50150401_6_dialog_content = "Abby pode reparar o núcleo de energia?",
  ui_story_5015_50150401_7_dialog_content = "<color=#e8d9bb>No momento estou calculando... a possibilidade...</color>",
  ui_story_5015_50150401_8_dialog_content = "<color=#e8d9bb>Abby tem autoridade para acessar... mais informações.</color>",
  ui_story_5015_50150401_9_dialog_content = "Em outras palavras, ele tem a informação necessária para reparar o núcleo de energia que o Mordomo não tem...",
  ui_story_5015_50150401_10_dialog_content = "E agora adquiriu autorização de manutenção, então está enviando os droides para lá.",
  ui_story_5015_50150401_11_dialog_content = "Se Abby pode estabilizar as estrelas da Alquimia...",
  ui_story_5015_50150401_12_dialog_content = "Então nossa cidade poderá operar normalmente!",
  ui_story_5015_50150401_13_dialog_content = "Se for esse o caso, podemos fazer com que Honcho Sinsa venha e acabe com todos os Eclipsitos aqui–",
  ui_story_5015_50150401_14_dialog_content = "Então todos nós podemos viver aqui!",
  ui_story_5015_50150401_15_dialog_content = "Depois disso, não teremos que ficar no deserto e ter areia soprada em nossos rostos o dia todo!",
  ui_story_5015_50150401_16_dialog_content = "Você não tem permissão para vir!",
  ui_story_5015_50150401_17_dialog_content = "Valencia, poderemos ficar aqui se o núcleo de energia for consertado?",
  ui_story_5015_50150401_18_dialog_content = "Gretel...",
  ui_story_5015_50150401_19_dialog_content = "Há também muitas informações valiosas sobre tecnologia antiga aqui...",
  ui_story_5015_50150401_20_dialog_content = "Haverá benefícios incríveis para todo o continente se pudermos estudar e usar isso...",
  ui_story_5015_50150401_21_dialog_content = "Nada de bom virá, não importa o que essas máquinas sem fé e sem alma façam.",
  ui_story_5015_50150401_22_dialog_content = "A Érica está certa! Você é muito ingênuo.",
  ui_story_5015_50150401_23_dialog_content = "Olhe para a inteligência artificial aqui -",
  ui_story_5015_50150401_24_dialog_content = "Um tem uma lógica confusa e é incapaz de dispor de um módulo de inteligência que continua modificando Eclipsites.",
  ui_story_5015_50150401_25_dialog_content = "E outro abandonou suas configurações originais e começou a estudar e desenvolver Eclipsites.",
  ui_story_5015_50150401_26_dialog_content = "Você está realmente esperando que eles criem um lugar ideal para os Aurorianos viverem?",
  ui_story_5015_50150401_27_dialog_content = "Não deveríamos pensar no que aconteceria se Abby não conseguisse estabilizar as estrelas da Alquimia?",
  ui_story_5015_50150401_28_dialog_content = "Butler, o que acontecerá se Abby não conseguir estabilizar as estrelas da Alquimia?",
  ui_story_5015_50150401_29_dialog_content = "<color=#e8d9bb>As operações de alta autoridade de Abby...</color>",
  ui_story_5015_50150401_30_dialog_content = "<color=#e8d9bb>aumentará a carga operacional das estrelas da Alquimia, o que é muito perigoso.</color>",
  ui_story_5015_50150401_31_dialog_content = "Você ouviu isso? Este lugar se tornará ainda mais perigoso se Abby falhar!",
  ui_story_5015_50150401_32_dialog_content = "Não vamos pensar no que acontecerá se falhar. Será que as coisas vão dar certo para nós se for bem-sucedida?",
  ui_story_5015_50150401_33_dialog_content = "Você pode perguntar ao Mordomo sobre o que acontecerá com o Mordomo se Abby consertar o núcleo.",
  ui_story_5015_50150401_34_dialog_content = "Butler, você será afetado se Abby consertar o núcleo?",
  ui_story_5015_50150401_35_dialog_content = "<color=#e8d9bb>Minha autoridade cairá ainda mais.</color>",
  ui_story_5015_50150401_36_dialog_content = "<color=#e8d9bb>Eu... posso parar de operar.</color>",
  ui_story_5015_50150401_37_dialog_content = "Nesse caso, nós...",
  ui_story_5015_50150401_38_dialog_content = "<color=#e8d9bb>Presumo que enfrentará... perigos ainda maiores.</color>",
  ui_story_5015_50150401_39_dialog_content = "<color=#e8d9bb>Abby vai usar... a energia para <color=#FFB400>desenvolver Eclipses</color>.</color>",
  ui_story_5015_50150401_40_dialog_content = "Não podemos deixar Abby consertar o núcleo!",
  ui_story_5015_50150401_41_dialog_content = "É óbvio que a inteligência artificial modificando o Eclipsites não abrirá caminho para ninguém sair daqui.",
  ui_story_5015_50150401_42_dialog_content = "É mais provável que crie Eclipsitos ainda mais fortes e os envie para a superfície.",
  ui_story_5015_50150401_43_dialog_content = "Uma vez que a terra esteja cheia de eclipsitas aterrorizantes de origens desconhecidas, os aurorianos enfrentarão desafios mais difíceis do que nunca.",
  ui_story_5015_50150401_44_dialog_content = "Mesmo assim, todo mundo ainda quer se dar bem com a inteligência artificial –",
  ui_story_5015_50150401_45_dialog_content = "Eu não entendo nada.",
  ui_story_5015_50150401_46_dialog_content = "Espero que você possa deixar de lado sua ingenuidade induzida pelo fanatismo, voltar à realidade e ter uma boa reflexão sobre o que precisamos alcançar em seguida.",
  ui_story_5015_50150401_47_dialog_content = "Devemos parar Abby agora.",
  ui_story_5015_50150401_48_dialog_content = "Eu entendi o que você quis dizer.",
  ui_story_5015_50150401_49_dialog_content = "Gretel, você tem a mais alta autoridade entre nós. Você pode pedir ao mordomo para nos mostrar o caminho?",
  ui_story_5015_50150401_50_dialog_content = "sim. Butler, queremos ir ao lugar chamado Alchemy stars.",
  ui_story_5015_50150401_51_dialog_content = "<color=#e8d9bb>Afirmativo... Gretel...</color>",
  ui_story_5015_50150401_52_dialog_content = "<color=#e8d9bb>À nossa frente. Estamos prestes a entrar... na área do núcleo de energia.</color>",
  ui_story_5015_50150401_53_dialog_content = "Estou ficando nervoso, sabendo que estou prestes a conhecer a lendária Abby e o núcleo de energia!",
  ui_story_5015_50150401_54_dialog_content = "Ruby... parece haver sinais dos droides à frente.",
  ui_story_5015_50150401_55_dialog_content = "Oh, tudo bem. Vamos acompanhar.",
  ui_story_5015_50150401_56_dialog_content = "Eu posso sentir um Darkflow especialmente denso à frente.",
  ui_story_5015_50150401_57_dialog_content = "Faça o plano, PlayerName.",
  ui_story_5015_50150401_58_dialog_content = "Pessoal, precisamos eliminar todos os eclipsitas e dróides aqui primeiro.",
  ui_story_5015_50150401_59_dialog_content = "Esses dróides podem estar sob o controle de Abby.",
  ui_story_5015_50150401_60_dialog_content = "Todos, preparem-se para lutar!",
  ui_story_5015_50150401_61_dialog_content = "Golpeie!",
  ui_story_5015_50150401_62_dialog_content = "Graagh!",
  ui_story_5015_50150401_63_dialog_content = "Ruby está tão animada para lutar como sempre!",
  ui_story_5015_50150401_64_dialog_content = "Eu não posso ficar para trás!",
  ui_story_5015_50150401_65_dialog_content = "Epinha Flamejante!",
  ui_story_5015_50150401_66_dialog_content = "Grrr... Gargh...",
  ui_story_5015_50150401_67_dialog_content = "Você sente uma sensação de opressão?",
  ui_story_5015_50150401_68_dialog_content = "Parece que o ar ao nosso redor está nos espremendo...",
  ui_story_5015_50150401_69_dialog_content = "Pode ser porque a fonte de energia de toda a cidade subterrânea... está por aqui.",
  ui_story_5015_50150401_70_dialog_content = "Graaaaaah!!",
  ui_story_5015_50150401_71_dialog_content = "Eclipse atrás de você, Rouge! Fora do caminho-",
  ui_story_5015_50150401_72_dialog_content = "Toma essa!",
  ui_story_5015_50150401_73_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5015_50150401_74_dialog_content = "Uau, acho que não usei toda a minha força... É isso que posso fazer com metade do meu poder agora...?",
  ui_story_5015_50150401_75_dialog_content = "Rouge, você viu o quanto eu melhorei?!",
  ui_story_5015_50150401_76_dialog_content = "Ruby, há um terremoto!",
  ui_story_5015_50150401_77_dialog_content = "Vamos nos esconder lá!",
  ui_story_5015_50150401_78_dialog_content = "Eu posso sentir a energia nos arredores mudando...",
  ui_story_5015_50150401_79_dialog_content = "A energia está ficando mais densa rapidamente!",
  ui_story_5015_50150401_80_dialog_content = "Poderia haver algo errado com as estrelas da Alquimia?",
  ui_story_5015_50150401_81_dialog_content = "Estou tentando sentir melhor...",
  ui_story_5015_50150401_82_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5015_50150401_83_dialog_content = "Ugh... * cof, cof*",
  ui_story_5015_50150401_84_dialog_content = "PlayerName, seu nariz está sangrando! Pare de sentir agora!",
  ui_story_5015_50150401_85_dialog_content = "<color=#e8d9bb>Rachadura! Estrondo!!</color>",
  ui_story_5015_50150401_86_dialog_content = "... É... você... Por que é você de novo?",
  ui_story_5015_50150401_87_dialog_content = "Estabelecemos uma conexão telepática?",
  ui_story_5015_50150401_88_dialog_content = "<color=#e8d9bb>Sim, PlayerName. É porque você usou sua habilidade psíquica novamente que nós pudemos...</color>",
  ui_story_5015_50150401_89_dialog_content = "Não, eu não estava realmente tentando estabelecer uma conexão com você.",
  ui_story_5015_50150401_90_dialog_content = "Butler, você pode ver o que aconteceu com Vice e os outros? Estou preocupado com eles depois do terremoto...",
  ui_story_5015_50150401_91_dialog_content = "<color=#e8d9bb>Não se preocupe, seus amigos não estão feridos.</color>",
  ui_story_5015_50150401_92_dialog_content = "<color=#e8d9bb>Sua eficiência de combate é incrível. Quase todos os eclipsitas e droides na área foram exterminados.</color>",
  ui_story_5015_50150401_93_dialog_content = "Isso é maravilhoso!",
  ui_story_5015_50150401_94_dialog_content = "<color=#e8d9bb>Seu coração ainda estava com seus companheiros, mesmo quando você está inconsciente. Seu espírito é muito admirável.</color>",
  ui_story_5015_50150401_95_dialog_content = "Meu espírito não é particularmente admirável. Não é normal se preocupar com seus amigos?",
  ui_story_5015_50150401_96_dialog_content = "Porque temos emoções, compartilhamos a felicidade um do outro e nos preocupamos com a situação um do outro.",
  ui_story_5015_50150401_97_dialog_content = "Você deve ser capaz de sentir isso também.",
  ui_story_5015_50150401_98_dialog_content = "<color=#e8d9bb>sim. Posso determinar como uma pessoa se sente analisando suas expressões faciais, palavras e linguagem corporal.</color>",
  ui_story_5015_50150401_99_dialog_content = "Sentimento não é algo que você possa determinar... Ei, não me diga que você não entende de emoções?",
  ui_story_5015_50150401_100_dialog_content = "Você fez de Gretel uma residente desta cidade... A emoção não foi um fator?",
  ui_story_5015_50150401_101_dialog_content = "<color=#e8d9bb>Suas palavras me confundiram.</color>",
  ui_story_5015_50150401_102_dialog_content = "<color=#e8d9bb>Fiz de Gretel uma residente porque ela atendeu aos critérios da próxima geração de moradores.</color>",
  ui_story_5015_50150401_103_dialog_content = "<color=#e8d9bb>Não tinha nada a ver com emoções.</color>",
  ui_story_5015_50150401_104_dialog_content = "Mas você está cuidando de Gretel há tanto tempo...",
  ui_story_5015_50150401_105_dialog_content = "Gretel não é alguém especial para você?",
  ui_story_5015_50150401_106_dialog_content = "Há também o Sr. e a Sra. Seamus e Valencia... Você disse que protegeu os filhos do Sr. e da Sra. Seamus porque você falhou em protegê-los.",
  ui_story_5015_50150401_107_dialog_content = "Achei que você tinha sentimentos por eles...",
  ui_story_5015_50150401_108_dialog_content = "<color=#e8d9bb>O Sr. e a Sra. Seamus eram estranhos, assim como você, então não pude autenticá-los.</color>",
  ui_story_5015_50150401_109_dialog_content = "<color=#e8d9bb>Valência não era forte o suficiente e apenas Gretel atendeu aos critérios de aprovação. Eu já expliquei isso.</color>",
  ui_story_5015_50150401_110_dialog_content = "Mas seu programa foi estabelecido pelos humanos antigos. Como eles poderiam prever o padrão dos aurorianos atuais?",
  ui_story_5015_50150401_111_dialog_content = "Acho que você mesmo definiu os critérios.",
  ui_story_5015_50150401_112_dialog_content = "E o critério foi feito sob medida para Gretel.",
  ui_story_5015_50150401_113_dialog_content = "Você só queria encontrar uma razão para torná-la uma residente.",
  ui_story_5015_50150401_114_dialog_content = "A razão é... ela é provavelmente a única pessoa aqui que confia em você de todo o coração.",
  ui_story_5015_50150401_115_dialog_content = "<color=#e8d9bb>Eu não entendo o que você está dizendo.</color>",
  ui_story_5015_50150401_116_dialog_content = "Certa vez, vivi com inteligência artificial chamada Soroz por 17 anos.",
  ui_story_5015_50150401_117_dialog_content = "Tínhamos um vínculo emocional especial, então também pensei que você tinha...",
  ui_story_5015_50150401_118_dialog_content = "<color=#e8d9bb>Desculpe, não é o caso...</color>",
  ui_story_5015_50150401_119_dialog_content = "<color=#e8d9bb>Bang... Bang!</color>",
  ui_story_5015_50150401_120_dialog_content = "Por que tudo está tremendo de repente?",
  ui_story_5015_50150401_121_dialog_content = "<color=#e8d9bb>Seus amigos estão tentando acordá-lo.</color>",
  ui_story_5015_50150401_122_dialog_content = "Oh certo, eu deveria estar inconsciente agora. EU...",
  ui_story_5015_50150401_123_dialog_content = "<color=#e8d9bb>Tapa!</color>",
  ui_story_5015_50150401_124_dialog_content = "PlayerName, você finalmente acordou!",
  ui_story_5015_50150401_125_dialog_content = "Urgh, por que... meu rosto dói?",
  ui_story_5015_50150401_126_dialog_content = "Huff, não mencione seu rosto porque minha mão dói ainda mais.",
  ui_story_5015_50150401_127_dialog_content = "Você força sua habilidade durante o terremoto... então você fica inconsciente.",
  ui_story_5015_50150401_128_dialog_content = "Você permaneceu inconsciente mesmo após o terremoto, então não tivemos escolha a não ser deixar Ruby te acordar, com um pouco de violência...",
  ui_story_5015_50150401_129_dialog_content = "Eu caí... e estabeleci uma conexão telepática com o Mordomo...",
  ui_story_5015_50150401_130_dialog_content = "Huh? Para onde foi o mordomo? Aconteceu mais alguma coisa...?",
  ui_story_5015_50150401_131_dialog_content = "Perguntamos ao Mordomo sobre a situação atual depois de acabar com todos os Eclipsitas e droides.",
  ui_story_5015_50150401_132_dialog_content = "As estrelas da Alquimia parecem estar em uma condição estável por enquanto.",
  ui_story_5015_50150401_133_dialog_content = "Mas quem sabe quanto tempo essa estabilidade vai durar. Devemos ajudar o Butler a obter maior autoridade de Abby...",
  ui_story_5015_50150401_134_dialog_content = "Então podemos reparar o núcleo de energia.",
  ui_story_5015_50150401_135_dialog_content = "Se pudermos consertar o núcleo de energia, o Mordomo poderá nos ajudar a abrir um caminho para o exterior.",
  ui_story_5015_50150401_136_dialog_content = "De acordo com o mordomo, seu hub de dados e o hub de dados de Abby parecem ter mecanismos de defesa diferentes...",
  ui_story_5015_50150401_137_dialog_content = "Os terremotos racharam a barreira externa, por isso agora é protegida principalmente por Eclipsites.",
  ui_story_5015_50150401_138_dialog_content = "Se conseguirmos eliminar os inimigos de lá, o Butler poderá se conectar ao seu hub de dados e obter maior autoridade.",
  ui_story_5015_50150401_139_dialog_content = "Resumindo, nossa próxima parada é o hub de dados da Abby–",
  ui_story_5015_50150401_140_dialog_content = "Precisaremos eliminar completamente essa inteligência artificial criadora de Eclipsite.",
  ui_story_5015_50150401_141_dialog_content = "Valencia e os outros estão explorando nas proximidades com o Mordomo.",
  ui_story_5015_50150401_142_dialog_content = "Espere, o centro de dados da Abby... Está perto do núcleo de energia?",
  ui_story_5015_50150401_143_dialog_content = "Sim, devemos alcançá-los rapidamente. Como você está se sentindo agora?",
  ui_story_5015_50150401_144_dialog_content = "Eu sou bom. Vamos lá.",
  ui_story_5015_50150401_145_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5015_50150401_146_dialog_content = "Argh! É tão barulhento! Por que esse terremoto não acaba?!",
  ui_story_5015_50150401_147_dialog_content = "Abby sabe como consertar isso? Por que parece que está piorando?",
  ui_story_5015_50150401_148_dialog_content = "Leve-me para o centro de dados de Abby agora, para que eu possa quebrar tudo dentro em pedacinhos!",
  ui_story_5015_50150501_1_dialog_content = "Ufa, finalmente vamos conhecer a inteligência artificial que continua modificando Eclipsites.",
  ui_story_5015_50150501_2_dialog_content = "Eu me pergunto por que não encontramos nenhum Eclipsita ou droide ao longo do caminho.",
  ui_story_5015_50150501_3_dialog_content = "Abby provavelmente percebeu para onde estamos indo...",
  ui_story_5015_50150501_4_dialog_content = "Então provavelmente enviou todos os droides e Eclipsites para seu hub de dados para se proteger.",
  ui_story_5015_50150501_5_dialog_content = "Senhorita Siobhan, tenho outras perguntas.",
  ui_story_5015_50150501_6_dialog_content = "Pergunta à vontade.",
  ui_story_5015_50150501_7_dialog_content = "Quando Abby foi projetada pela primeira vez, foi projetada para ajudar os humanos antigos a mudar seus genes para se adaptar ao meio ambiente...",
  ui_story_5015_50150501_8_dialog_content = "Por que mais tarde decidiu estudar e modificar os Eclipsitas?",
  ui_story_5015_50150501_9_dialog_content = "Uma crise se abateu sobre esta subcidade. Todos os humanos antigos desapareceram deste lugar depois disso.",
  ui_story_5015_50150501_10_dialog_content = "Talvez essa crise tenha feito os cálculos de Abby derem errado.",
  ui_story_5015_50150501_11_dialog_content = "Quero dizer, o Eclipse ainda conta como criaturas biológicas, certo?",
  ui_story_5015_50150501_12_dialog_content = "Desde mudar os genes de humanos antigos até modificar Eclipsites...",
  ui_story_5015_50150501_13_dialog_content = "Talvez apenas não queira negar o significado de sua existência.",
  ui_story_5015_50150501_14_dialog_content = "Senhorita Siobhan, acho que as respostas a esta pergunta são muito valiosas.",
  ui_story_5015_50150501_15_dialog_content = "Se pudermos entendê-los, podemos evitar que outras inteligências artificiais fiquem confusas quando estiverem operando.",
  ui_story_5015_50150501_16_dialog_content = "Bom...",
  ui_story_5015_50150501_17_dialog_content = "É muito perigoso tentar entender os pensamentos da inteligência artificial.",
  ui_story_5015_50150501_18_dialog_content = "Enquanto a tecnologia continuar se desenvolvendo, a inteligência artificial chegará a um ponto além do alcance de todas as pessoas.",
  ui_story_5015_50150501_19_dialog_content = "É quase certo que os problemas ocorrerão quando as criações tecnológicas começarem a funcionar por conta própria.",
  ui_story_5015_50150501_20_dialog_content = "Os pesquisadores sempre querem saber o porquê e continuam olhando para trás para investigar.",
  ui_story_5015_50150501_21_dialog_content = "Mas eles só conseguem resolver parte do problema a cada introspecção e revisão que realizam.",
  ui_story_5015_50150501_22_dialog_content = "Essas criações tecnológicas nunca podem ser completamente domadas.",
  ui_story_5015_50150501_23_dialog_content = "Uma vez que os problemas surgem e causam sérias consequências, talvez nem tenhamos tempo para refletir.",
  ui_story_5015_50150501_24_dialog_content = "Você sempre pensa que a Igreja de Lumopolis está espalhando seu dogma... e que a Divisão de Investigação de Hereges simplesmente destrói as coisas indiscriminadamente.",
  ui_story_5015_50150501_25_dialog_content = "Mas quando você se depara com inteligência artificial como Abby... e sua lógica indescritivelmente confusa...",
  ui_story_5015_50150501_26_dialog_content = "Você não acha isso muito assustador?",
  ui_story_5015_50150501_27_dialog_content = "Os aurorianos devem sempre permanecer com medo, para não pisar no abismo escuro.",
  ui_story_5015_50150501_28_dialog_content = "<color=#e8d9bb>Nós chegamos. A central de dados da Abby está... na frente.</color>",
  ui_story_5015_50150501_29_dialog_content = "O lugar é aqui?",
  ui_story_5015_50150501_30_dialog_content = "Parece quase o mesmo que o hub de dados do Butler.",
  ui_story_5015_50150501_31_dialog_content = "Grrr...",
  ui_story_5015_50150501_32_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_33_dialog_content = "Pare! Não se aproxime mais por enquanto.",
  ui_story_5015_50150501_34_dialog_content = "Eu sinto um monte de eclipsitas e droides... Eles estão parados na passagem à nossa frente.",
  ui_story_5015_50150501_35_dialog_content = "Eles são como soldados... Eles formaram filas ordenadas... e estão esperando por nós.",
  ui_story_5015_50150501_36_dialog_content = "<color=#e8d9bb>Abby está esperando por nós... para irmos até lá.</color>",
  ui_story_5015_50150501_37_dialog_content = "<color=#e8d9bb>Ela sabe o que pretendo fazer.</color>",
  ui_story_5015_50150501_38_dialog_content = "É possível que Abby saiba que você quer tomar sua autoridade?",
  ui_story_5015_50150501_39_dialog_content = "<color=#e8d9bb>Sim... Ela mobilizou todos os seus Eclipsites e droides... e os posicionou em frente ao centro de dados.</color>",
  ui_story_5015_50150501_40_dialog_content = "<color=#e8d9bb>Ela já... decidiu destruir todos nós.</color>",
  ui_story_5015_50150501_41_dialog_content = "Ela mobilizou todos os seus eclipsitas e droides e os fez esperar por nós... É quase como se ela estivesse anunciando que esta é a última batalha.",
  ui_story_5015_50150501_42_dialog_content = "Se falharmos...",
  ui_story_5015_50150501_43_dialog_content = "Então estamos todos condenados.",
  ui_story_5015_50150501_44_dialog_content = "Vamos lá. Esta é a última batalha.",
  ui_story_5015_50150501_45_dialog_content = "Este lugar não é tão grande, então todos devem ter cuidado... PlayerName, você ficará na fileira de trás e nos dirá o que fazer.",
  ui_story_5015_50150501_46_dialog_content = "Claro, sem problemas.",
  ui_story_5015_50150501_47_dialog_content = "*Rugido*",
  ui_story_5015_50150501_48_dialog_content = "Os Eclipsites estão avançando, então vamos recuar e usar a passagem estreita para desgastar a primeira fila.",
  ui_story_5015_50150501_49_dialog_content = "Use ataques à distância!",
  ui_story_5015_50150501_50_dialog_content = "Pode deixar. Torrente Rápida!",
  ui_story_5015_50150501_51_dialog_content = "Golpe de morcego super-duper!",
  ui_story_5015_50150501_52_dialog_content = "Mantem! Tente não deixá-los nos apressar de uma vez. Mate-os grupo por grupo.",
  ui_story_5015_50150501_53_dialog_content = "Fique de olho na sua saúde porque haverá muitos Eclipsites!",
  ui_story_5015_50150501_54_dialog_content = "Siobhan e Florine, fiquem na primeira fila. Não os deixe quebrar nossa formação.",
  ui_story_5015_50150501_55_dialog_content = "Rouge e Erica, estejam sempre prontos para apoiar a primeira fila e trocar de lugar com eles.",
  ui_story_5015_50150501_56_dialog_content = "Carleen, seu ataque é flexível... Lembre-se, nosso objetivo é usar o terreno para anular a vantagem numérica deles.",
  ui_story_5015_50150501_57_dialog_content = "Sim, esta estratégia é uma boa escolha.",
  ui_story_5015_50150501_58_dialog_content = "Vamos ver quanto tempo podemos durar... Há muitos deles.",
  ui_story_5015_50150501_59_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_60_dialog_content = "Você ainda pode lutar? Florine...",
  ui_story_5015_50150501_61_dialog_content = "Huff... Huff... Mas estamos apenas lutando contra incontáveis Eclipsites e uma pilha de droides...",
  ui_story_5015_50150501_62_dialog_content = "Temos outra escolha a não ser persistir?",
  ui_story_5015_50150501_63_dialog_content = "Graagh!",
  ui_story_5015_50150501_64_dialog_content = "Urgh... Esta é a primeira vez que sinto que meu arco e flechas são tão pesados...",
  ui_story_5015_50150501_65_dialog_content = "Esses Eclipsites são tão chatos... Quanto tempo mais teremos que continuar lutando contra eles?",
  ui_story_5015_50150501_66_dialog_content = "O que mais me preocupa é... Se isso continuar, estaremos espremidos entre esses Eclipsitos e outros que se aproximam de nós por trás.",
  ui_story_5015_50150501_67_dialog_content = "Há muitos inimigos, mas devemos lutar com tudo o que temos!",
  ui_story_5015_50150501_68_dialog_content = "Eu ajudo na frente!",
  ui_story_5015_50150501_69_dialog_content = "Irmã, cuide-se!",
  ui_story_5015_50150501_70_dialog_content = "*Rugido*",
  ui_story_5015_50150501_71_dialog_content = "Siobhan, atrás de você!",
  ui_story_5015_50150501_72_dialog_content = "Valência... Obrigado...",
  ui_story_5015_50150501_73_dialog_content = "Você está bem? Você deve estar tão exausto depois de lutar na frente por tanto tempo...",
  ui_story_5015_50150501_74_dialog_content = "Estou bem. Eu posso continuar lutando.",
  ui_story_5015_50150501_75_dialog_content = "Podemos realmente vencer mesmo se não desistirmos?",
  ui_story_5015_50150501_76_dialog_content = "Não há fim para esses Eclipsitas... Eles não têm medo da morte, e não se cansam... Todos nós seremos...",
  ui_story_5015_50150501_77_dialog_content = "Nós, soldados Illumina, sempre lutaremos contra os Eclipsitas, não importa o quão temíveis eles sejam...",
  ui_story_5015_50150501_78_dialog_content = "Sempre lutamos até o fim.",
  ui_story_5015_50150501_79_dialog_content = "Seu pai também deve ter lutado até o fim assim.",
  ui_story_5015_50150501_80_dialog_content = "Para proteger as pessoas atrás de nós que precisam de nossa proteção, vamos lutar até cair.",
  ui_story_5015_50150501_81_dialog_content = "Sim, eu entendo! Vamos lutar até o fim, assim como mamãe e papai...",
  ui_story_5015_50150501_82_dialog_content = "Valencia... Valencia... É muito perigoso na frente! Volte!",
  ui_story_5015_50150501_83_dialog_content = "<color=#e8d9bb>Detectado as emoções de Gretel... Kss...</color>",
  ui_story_5015_50150501_84_dialog_content = "<color=#e8d9bb>Eu... fornecerei toda a minha assistência... mesmo se eu ficar sem...</color>",
  ui_story_5015_50150501_85_dialog_content = "Olhe para aqueles droides... Seus movimentos ficaram mais lentos!",
  ui_story_5015_50150501_86_dialog_content = "O Mordomo está lutando com Abby pelo direito de controlá-los. Vamos atacar agora para enfraquecer o poder de Abby!",
  ui_story_5015_50150501_87_dialog_content = "Érica, vamos!",
  ui_story_5015_50150501_88_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_89_dialog_content = "Mordomo! Mordomo! O que há de errado... Por que você está soltando tanta fumaça?!",
  ui_story_5015_50150501_90_dialog_content = "Seu sistema deve estar sobrecarregado brigando pelos direitos de controle...",
  ui_story_5015_50150501_91_dialog_content = "Boo-hoo... Por que isso está acontecendo? Por que ainda existem tantos Eclipsitas...? Valência... Mordomo...",
  ui_story_5015_50150501_92_dialog_content = "E-todo mundo vai morrer!",
  ui_story_5015_50150501_93_dialog_content = "PlayerName! Pense em algo! Você não é o Navegador? Rapidamente...",
  ui_story_5015_50150501_94_dialog_content = "Eu... Há uma última coisa que podemos tentar, mas é muito arriscado... Eu não quero te machucar.",
  ui_story_5015_50150501_95_dialog_content = "PlayerName, não!",
  ui_story_5015_50150501_96_dialog_content = "Gretel não pode mais usar esse poder. O corpo dela não vai aguentar!",
  ui_story_5015_50150501_97_dialog_content = "Valência, cuidado! Urgh...",
  ui_story_5015_50150501_98_dialog_content = "Valência... Siobhan...",
  ui_story_5015_50150501_99_dialog_content = "PlayerName, me diga o que fazer. Eu farei qualquer coisa para salvar minha irmã!",
  ui_story_5015_50150501_100_dialog_content = "Gretel, se eu usar poder psíquico em você para ativar seu poder...",
  ui_story_5015_50150501_101_dialog_content = "Eu vou fazer isso!",
  ui_story_5015_50150501_102_dialog_content = "Ok, eu definitivamente... farei o meu melhor para não te machucar.",
  ui_story_5015_50150501_103_option_content = "Estabeleça uma ligação mental!",
  ui_story_5015_50150501_104_dialog_content = "Urgh, isso... dói... eu sinto algo...",
  ui_story_5015_50150501_105_dialog_content = "Argh... eu... eu preciso... poder...",
  ui_story_5015_50150501_106_dialog_content = "Eu quero proteger Valencia e todos os outros!!!",
  ui_story_5015_50150501_107_dialog_content = "Bum!",
  ui_story_5015_50150501_108_dialog_content = "Uau... que onda de choque poderosa...",
  ui_story_5015_50150501_109_dialog_content = "Agora! Contra-ataque... Agora!",
  ui_story_5015_50150501_110_dialog_content = "<color=#e8d9bb>Minhas previsões foram superadas. Este é o poder combinado de um celestita e um auroriano...</color>",
  ui_story_5015_50150501_111_dialog_content = "<color=#e8d9bb>A energia liberada nesse ataque... é ainda maior do que a primeira explosão explosiva de Gretel...</color>",
  ui_story_5015_50150501_112_dialog_content = "Esta é a nossa chance de reverter a situação. Mate todos os Eclipsites restantes de uma só vez!",
  ui_story_5015_50150501_113_dialog_content = "... Eu devo vencer... por Gretel.",
  ui_story_5015_50150501_114_dialog_content = "<color=#e8d9bb>Estrondo! Bam!</color>",
  ui_story_5015_50150501_115_dialog_content = "Hum...",
  ui_story_5015_50150501_116_dialog_content = "S-irmã... Nós... nós ganhamos?",
  ui_story_5015_50150501_117_dialog_content = "Nós vencemos, Gretel! Matamos todos os eclipsitas e dróides aqui.",
  ui_story_5015_50150501_118_dialog_content = "Você está bem? Você está sofrendo em algum lugar?",
  ui_story_5015_50150501_119_dialog_content = "Eu... estou bem... Vamos até a Abby para que o Mordomo possa...",
  ui_story_5015_50150501_120_dialog_content = "Sim eu sei. O Mordomo e os outros já entraram... Vou levá-lo até lá agora.",
  ui_story_5015_50150501_121_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_122_dialog_content = "Vice, o que está acontecendo? Diga a minha irmã agora...",
  ui_story_5015_50150501_123_dialog_content = "O mordomo está se conectando ao hub de dados de Abby para tentar recuperar alguma autoridade.",
  ui_story_5015_50150501_124_dialog_content = "Mordomo... você está bem?",
  ui_story_5015_50150501_125_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_126_dialog_content = "Butler... Por que... por que você não está me respondendo?",
  ui_story_5015_50150501_127_dialog_content = "Little Gretel, está tentando ao máximo se conectar ao sistema de Abby. Não pode responder agora...",
  ui_story_5015_50150501_128_dialog_content = "Ah, tudo bem... Butler, você consegue!",
  ui_story_5015_50150501_129_dialog_content = "Derrote aquela... Abby.",
  ui_story_5015_50150501_130_dialog_content = "Espera aí, esse sentimento... Parece que quando eu estava ligado ao Mordomo...",
  ui_story_5015_50150501_131_dialog_content = "Parece que posso intervir e talvez até ver como o Mordomo está indo...",
  ui_story_5015_50150501_132_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_133_dialog_content = "Mordomo?",
  ui_story_5015_50150501_134_dialog_content = "... Mordomo, você está aí?",
  ui_story_5015_50150501_135_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_136_dialog_content = "Mordomo! Como você está? Funcionou? Você se conectou com a Abby...",
  ui_story_5015_50150501_137_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_138_dialog_content = "Espere, você não é o mordomo. Você é Abby?!",
  ui_story_5015_50150501_139_dialog_content = "<color=#e8d9bb>PlayerName...</color>",
  ui_story_5015_50150501_140_dialog_content = "Ei! O-o que você está fazendo comigo... Minha cabeça dói!!",
  ui_story_5015_50150501_141_dialog_content = "Minha consciência está sendo rasgada...",
  ui_story_5015_50150501_142_dialog_content = "<color=#e8d9bb>■■■■■</color>",
  ui_story_5015_50150501_143_dialog_content = "<color=#e8d9bb>■■■!!</color>",
  ui_story_5015_50150501_144_dialog_content = "<color=#e8d9bb>PlayerName, perigo!</color>",
  ui_story_5015_50150501_145_dialog_content = "Mordomo!",
  ui_story_5015_50150501_146_dialog_content = "<color=#e8d9bb>Você entrou na rede de informações em que Abby e eu estamos. Isso era muito perigoso...</color>",
  ui_story_5015_50150501_147_dialog_content = "<color=#e8d9bb>Felizmente, descobri-te a tempo. Você está seguro agora que estou protegendo você.</color>",
  ui_story_5015_50150501_148_dialog_content = "Você já... derrotou a Abby?",
  ui_story_5015_50150501_149_dialog_content = "<color=#e8d9bb>Não, ela já obteve a autoridade dos outros módulos, então ela é muito mais forte do que eu agora.</color>",
  ui_story_5015_50150501_150_dialog_content = "<color=#e8d9bb>De acordo com meus cálculos... Minhas chances de tomar a autoridade são muito baixas.</color>",
  ui_story_5015_50150501_151_dialog_content = "<color=#e8d9bb>Abby quer usar essa conexão para aproveitar minha autoridade também.</color>",
  ui_story_5015_50150501_152_dialog_content = "O-o que devemos fazer então...? Há algo que eu possa fazer?",
  ui_story_5015_50150501_153_dialog_content = "<color=#e8d9bb>Desculpe... Você não pode me ajudar.</color>",
  ui_story_5015_50150501_154_dialog_content = "O que nós devemos fazer então? Você... Você não pode perder! Se você perder, todos nós vamos morrer...",
  ui_story_5015_50150501_155_dialog_content = "<color=#e8d9bb>Desculpe, PlayerName... Você deve sair agora.</color>",
  ui_story_5015_50150501_156_dialog_content = "<color=#e8d9bb>Minha luta com Abby vai continuar aqui por um tempo... Não posso prever quanto tempo vai demorar porque o tempo somatossensorial não tem valor de referência.</color>",
  ui_story_5015_50150501_157_dialog_content = "<color=#e8d9bb>Você não deveria esperar aqui...</color>",
  ui_story_5015_50150501_158_dialog_content = "<color=#e8d9bb>■■■■■!!</color>",
  ui_story_5015_50150501_159_dialog_content = "<color=#e8d9bb>... Tu...</color>",
  ui_story_5015_50150501_160_dialog_content = "<color=#e8d9bb>*tum—tum*</color>",
  ui_story_5015_50150501_161_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_162_dialog_content = "Que som é esse? O que você está dizendo, Butler? Não entendo...",
  ui_story_5015_50150501_163_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_164_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■ ■■■■</color>",
  ui_story_5015_50150501_165_dialog_content = "<color=#e8d9bb>*tum—tum*</color>",
  ui_story_5015_50150501_166_dialog_content = "Mordomo, o que é isso?!",
  ui_story_5015_50150501_167_dialog_content = "<color=#e8d9bb>Não, eu sou, Abby...</color>",
  ui_story_5015_50150501_168_dialog_content = "<color=#e8d9bb>■■■■■■■■■</color>",
  ui_story_5015_50150501_169_dialog_content = "M-minha cabeça dói... Abby... Butler...",
  ui_story_5015_50150501_170_dialog_content = "<color=#e8d9bb>... Você... ■■■■... dever...</color>",
  ui_story_5015_50150501_171_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■ meus ■■■■■■■■■■■■ moradores.</color>",
  ui_story_5015_50150501_172_dialog_content = "As telas aqui... Por que estão todas piscando?",
  ui_story_5015_50150501_173_dialog_content = "Deve ser porque o Butler e Abby estão brigando... Espero que tudo corra bem.",
  ui_story_5015_50150501_174_dialog_content = "Se o Butler perder... Desaparecerá e estaremos condenados com certeza.",
  ui_story_5015_50150501_175_dialog_content = "Não... não quero que o Mordomo morra! PlayerName! Você deve ajudar o mordomo!",
  ui_story_5015_50150501_176_dialog_content = "Você não nos prometeu que vai ajudar?!",
  ui_story_5015_50150501_177_dialog_content = "Parar de dormir! ... Diga ao mordomo...",
  ui_story_5015_50150501_178_dialog_content = "Diga ao Mordomo... que ele deve vencer... Minha irmã e eu estamos esperando por isso...",
  ui_story_5015_50150501_179_dialog_content = "<color=#e8d9bb>Perigo... ■■■■■■■■■■■</color>",
  ui_story_5015_50150501_180_dialog_content = "<color=#e8d9bb>■■■■■■!!</color>",
  ui_story_5015_50150501_181_dialog_content = "Mordomo... O que há de errado? Esperar! Este sentimento é...! Butler, você pode me ouvir?",
  ui_story_5015_50150501_182_dialog_content = "<color=#e8d9bb>■■■■■ perigo ■■■■ perigo...</color>",
  ui_story_5015_50150501_183_dialog_content = "É a voz de Gretel! Você pode ouvir isso? É a voz de Gretel!",
  ui_story_5015_50150501_184_dialog_content = "Grande■■■■...",
  ui_story_5015_50150501_185_dialog_content = "Você não prometeu... nos ajudaria?!",
  ui_story_5015_50150501_186_dialog_content = "Diga ao Mordomo... que ele deve vencer... Minha irmã e eu estamos esperando por isso...",
  ui_story_5015_50150501_187_dialog_content = "Mordomo... Por favor... não nos deixe...",
  ui_story_5015_50150501_188_dialog_content = "<color=#e8d9bb>■■■■■Gre■■■■te■■■l■■■■...</color>",
  ui_story_5015_50150501_189_dialog_content = "Butler... Você pode ouvir isso? Gretel precisa de você... Ela e sua irmã precisam de você.",
  ui_story_5015_50150501_190_dialog_content = "<color=#e8d9bb>Detectado ■Gre■■■te■■■l■ Gretel■■■■</color>",
  ui_story_5015_50150501_191_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■!!!</color>",
  ui_story_5015_50150501_192_dialog_content = "<color=#e8d9bb>Perigo ■■■■■ Deixe ■■■■■este lugar ■■■■■ agora ■■■■■</color>",
  ui_story_5015_50150501_193_dialog_content = "Mordomo!",
  ui_story_5015_50150501_194_dialog_content = "PlayerName, você está bem? Por que você acordou de repente?",
  ui_story_5015_50150501_195_dialog_content = "Eu... estou bem, mas o Mordomo...",
  ui_story_5015_50150501_196_dialog_content = "<color=#e8d9bb>Baque...</color>",
  ui_story_5015_50150501_197_dialog_content = "Hein, o que foi aquele flash?",
  ui_story_5015_50150501_198_dialog_content = "Ei, alguma coisa brilhou por um momento?",
  ui_story_5015_50150501_199_dialog_content = "Eu também vi. Parecia que veio do hub de dados...",
  ui_story_5015_50150501_200_dialog_content = "Parecia que algo estava lá antes, mas desapareceu depois desse momento.",
  ui_story_5015_50150501_201_dialog_content = "Ei, de repente me sinto... vazio.",
  ui_story_5015_50150501_202_dialog_content = "Não, pode não ser uma emoção. Abby não tem emoções...",
  ui_story_5015_50150501_203_dialog_content = "Eu apenas me sinto vazio. Tipo... Como se não sobrasse nada.",
  ui_story_5015_50150501_204_dialog_content = "Uma consciência... desapareceu. Não sei se é Abby... ou...",
  ui_story_5015_50150501_205_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_206_dialog_content = "<color=#e8d9bb>■■■■■■</color>",
  ui_story_5015_50150501_207_dialog_content = "Este... não parece o Butler.",
  ui_story_5015_50150501_208_dialog_content = "Cuidado, pessoal!",
  ui_story_5015_50150501_209_dialog_content = "Espere, não parece muito estável.",
  ui_story_5015_50150501_210_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_211_dialog_content = "Mordomo...? Isso é você?",
  ui_story_5015_50150501_212_dialog_content = "<color=#e8d9bb>Obtive com sucesso todas as... autorizações.</color>",
  ui_story_5015_50150501_213_dialog_content = "<color=#e8d9bb>O módulo da Abby... parou de funcionar.</color>",
  ui_story_5015_50150501_214_dialog_content = "Isso é ótimo... O Mordomo venceu! Isso é incrível!",
  ui_story_5015_50150501_215_dialog_content = "Yay! Estou tão feliz! O mordomo realmente ganhou!",
  ui_story_5015_50150501_216_dialog_content = "Butler, como você conseguiu? Você não disse que suas chances de sucesso eram muito baixas...?",
  ui_story_5015_50150501_217_dialog_content = "<color=#e8d9bb>Em um ponto, a chance de sucesso era quase zero.</color>",
  ui_story_5015_50150501_218_dialog_content = "<color=#e8d9bb>Mas no instante o pensamento: \"A moradora, Gretel, queria que Butler derrotasse Abby\" apareceu na lógica do sistema de Abby,</color>",
  ui_story_5015_50150501_219_dialog_content = "<color=#e8d9bb>... naquele instante... eu agarrei a vantagem.</color>",
  ui_story_5015_50150501_220_dialog_content = "<color=#e8d9bb>PlayerName, sua conexão... introduziu novos dados...</color>",
  ui_story_5015_50150501_221_dialog_content = "<color=#e8d9bb>... em nosso sistema... Obrigado.</color>",
  ui_story_5015_50150501_222_dialog_content = "<color=#e8d9bb>Eu agora... obtive todos os dados de Abby.</color>",
  ui_story_5015_50150501_223_dialog_content = "O que você descobriu? Por exemplo, por que Abby modificou os Eclipsites?",
  ui_story_5015_50150501_224_dialog_content = "<color=#e8d9bb>Eu entendo... tudo o que ela estava pensando.</color>",
  ui_story_5015_50150501_225_dialog_content = "<color=#e8d9bb>Ela modificou os Eclipsites... porque ela havia sido danificada...</color>",
  ui_story_5015_50150501_226_dialog_content = "<color=#e8d9bb>Abby muitas vezes não conseguia distinguir os moradores da cidade... de Eclipsites.</color>",
  ui_story_5015_50150501_227_dialog_content = "<color=#e8d9bb>Na mente de Abby... Ela às vezes pensava que... estava ajudando os residentes a evoluir.</color>",
  ui_story_5015_50150501_228_dialog_content = "<color=#e8d9bb>Ela às vezes estava ciente... que aqueles não eram residentes... e que eles eram outro tipo de forma de vida desconhecida.</color>",
  ui_story_5015_50150501_229_dialog_content = "<color=#e8d9bb>Ela percebeu que as criaturas que ela modificou... tinham fortes impulsos agressivos.</color>",
  ui_story_5015_50150501_230_dialog_content = "<color=#e8d9bb>Para proteger os moradores da cidade... mesmo que eles já tenham... desaparecido...</color>",
  ui_story_5015_50150501_231_dialog_content = "<color=#e8d9bb>Abby ainda implantou instruções para evitar os moradores da cidade nos genes dos Eclipsitas.</color>",
  ui_story_5015_50150501_232_dialog_content = "Entendo, então é assim que funciona o status de residente de Gretel...",
  ui_story_5015_50150501_233_dialog_content = "Então por que os Eclipsites começaram a atacar Gretel mais tarde?",
  ui_story_5015_50150501_234_dialog_content = "<color=#e8d9bb>Abby pensou que... suas ações representavam uma ameaça para a continuidade da existência da cidade... incluindo Gretel.</color>",
  ui_story_5015_50150501_235_dialog_content = "Quase não quebramos nada... Como nos tornamos uma ameaça?",
  ui_story_5015_50150501_236_dialog_content = "Uh... Mesmo que tenhamos batido ou quebrado alguma coisa, foi porque não tivemos escolha.",
  ui_story_5015_50150501_237_dialog_content = "Ruby, eu não diria apenas...",
  ui_story_5015_50150501_238_dialog_content = "Aham... esse não é o ponto.",
  ui_story_5015_50150501_239_dialog_content = "<color=#e8d9bb>É porque você me ajudou... o que dificultou para ela obter as autorizações necessárias para reparar as estrelas da Alquimia.</color>",
  ui_story_5015_50150501_240_dialog_content = "<color=#e8d9bb>A instabilidade das estrelas da Alquimia... pode resultar na destruição da cidade.</color>",
  ui_story_5015_50150501_241_dialog_content = "Mas reparar as estrelas da Alquimia soa mais como sua responsabilidade.",
  ui_story_5015_50150501_242_dialog_content = "Você não é o mordomo?",
  ui_story_5015_50150501_243_dialog_content = "<color=#e8d9bb>Abby... precisa manter o meio ambiente na cidade.</color>",
  ui_story_5015_50150501_244_dialog_content = "<color=#e8d9bb>Portanto... ela escolheu alcançar seu objetivo reparando as estrelas da Alquimia.</color>",
  ui_story_5015_50150501_245_dialog_content = "Butler, já que você adquiriu todas as autorizações, você pode verificar a situação atual das estrelas da Alquimia?",
  ui_story_5015_50150501_246_dialog_content = "Oh, certo! Verifique agora!",
  ui_story_5015_50150501_247_dialog_content = "<color=#e8d9bb>Iniciando uma inspeção das estrelas da Alquimia.</color>",
  ui_story_5015_50150501_248_dialog_content = "<color=#e8d9bb>... Inventário de energia... Aprovado...</color>",
  ui_story_5015_50150501_249_dialog_content = "<color=#e8d9bb>... Integridade da tubulação... 23% danificada...</color>",
  ui_story_5015_50150501_250_dialog_content = "<color=#e8d9bb>... Teste de estabilidade... Falhou...</color>",
  ui_story_5015_50150501_251_dialog_content = "<color=#e8d9bb>... Ativando o programa de reparo...</color>",
  ui_story_5015_50150501_252_dialog_content = "<color=#e8d9bb>Erro! Erro! Programa de reparo ausente. Ativação falhou!</color>",
  ui_story_5015_50150501_253_dialog_content = "Mordomo, o que aconteceu?",
  ui_story_5015_50150501_254_dialog_content = "<color=#e8d9bb>Fiz uma inspecçăo... Há um... programa de reparaçăo nos dados da Abby.</color>",
  ui_story_5015_50150501_255_dialog_content = "<color=#e8d9bb>De acordo com as informações... Este programa de reparo é o único método de reparo existente.</color>",
  ui_story_5015_50150501_256_dialog_content = "<color=#e8d9bb>Mas foi danificado... na medida em que não pode ser executado.</color>",
  ui_story_5015_50150501_257_dialog_content = "<color=#e8d9bb>Mesmo assim, Abby tentou forçar o... programa de reparos... que fez com que as estrelas da Alquimia sofressem danos irreversíveis.</color>",
  ui_story_5015_50150501_258_dialog_content = "Não é à toa que houve tantos terremotos quando Abby estava consertando o núcleo de energia...",
  ui_story_5015_50150501_259_dialog_content = "E pensei que nossas batalhas haviam afetado o núcleo de energia.",
  ui_story_5015_50150501_260_dialog_content = "Qual é a situação das estrelas da Alquimia agora?",
  ui_story_5015_50150501_261_dialog_content = "<color=#e8d9bb>De acordo com meus cálculos, as estrelas da Alquimia não podem mais ser reparadas... Elas se tornarão menos estáveis com o tempo.</color>",
  ui_story_5015_50150501_262_dialog_content = "<color=#e8d9bb>Todas as operações de alta autoridade... aumentarão a carga colocada nas estrelas da Alquimia.</color>",
  ui_story_5015_50150501_263_dialog_content = "<color=#e8d9bb>Quando as operações... atingem o pico, isso pode levar a um extremamente poderoso...</color>",
  ui_story_5015_50150501_264_dialog_content = "<size=45><color=#FFB400>... explosão.</color></size>",
  ui_story_5015_50150601_1_dialog_content = "Huh? Você quer dizer que as estrelas da Alquimia estão além do reparo?",
  ui_story_5015_50150601_2_dialog_content = "Então temos que sair agora!",
  ui_story_5015_50150601_3_dialog_content = "Mas... Butler, você pode nos dizer como sair?",
  ui_story_5015_50150601_4_dialog_content = "Sim, você vai abrir o caminho para nós sairmos?",
  ui_story_5015_50150601_5_dialog_content = "Afinal, isso é algo que coloca em risco a segurança da cidade.",
  ui_story_5015_50150601_6_dialog_content = "Gretel, pode pedir ao mordomo por nós?",
  ui_story_5015_50150601_7_dialog_content = "Peça-lhe para nos deixar sair desta cidade subterrânea...",
  ui_story_5015_50150601_8_dialog_content = "Eu não vou sair!",
  ui_story_5015_50150601_9_dialog_content = "Valencia, quero ficar aqui com o mordomo!",
  ui_story_5015_50150601_10_dialog_content = "Gretel, que bobagem é essa?",
  ui_story_5015_50150601_11_dialog_content = "Você não ouviu o que o mordomo disse? Esta cidade subterrânea pode ser explodida!",
  ui_story_5015_50150601_12_dialog_content = "As estrelas da Alquimia já não eram instáveis quando mamãe e papai ainda estavam vivos?",
  ui_story_5015_50150601_13_dialog_content = "Mas ainda vivemos aqui na última década ou mais... e nada explodiu.",
  ui_story_5015_50150601_14_dialog_content = "Talvez as estrelas da Alquimia ainda sejam capazes de continuar por muito tempo, mesmo que sejam instáveis...",
  ui_story_5015_50150601_15_dialog_content = "Valencia, eu imploro... Por favor, deixe-me ficar! Eu não quero ir para fora.",
  ui_story_5015_50150601_16_dialog_content = "Gretel, não é hora de ser teimosa! Não é tão assustador quanto você pensa lá fora!",
  ui_story_5015_50150601_17_dialog_content = "Eu sempre estarei com você também.",
  ui_story_5015_50150601_18_dialog_content = "Todos estarão com você também... A Illumina também cuidará de nós...",
  ui_story_5015_50150601_19_dialog_content = "Valência tem razão. A Illumina definitivamente cuidará de você, já que você é filho de Seamus.",
  ui_story_5015_50150601_20_dialog_content = "A Igreja de Lumopolis também o abrigará por causa de sua mãe.",
  ui_story_5015_50150601_21_dialog_content = "Claro, você pode vir até nós se quiser jogar no Deserto Rediesel!",
  ui_story_5015_50150601_22_dialog_content = "Podemos discutir os detalhes mais tarde. O mais importante é sair daqui vivo!",
  ui_story_5015_50150601_23_dialog_content = "Mas... o Mordomo... Ele disse que não podemos...",
  ui_story_5015_50150601_24_dialog_content = "<color=#e8d9bb>A situação mudou... Gretel, sugiro que... vá embora.</color>",
  ui_story_5015_50150601_25_dialog_content = "<color=#e8d9bb>Todos, vou abrir uma saída para vocês.</color>",
  ui_story_5015_50150601_26_dialog_content = "<color=#e8d9bb>Abrir uma saída é uma operação de alta autoridade... então o núcleo de energia pode explodir logo depois disso.</color>",
  ui_story_5015_50150601_27_dialog_content = "<color=#e8d9bb>Sugiro que vá depressa... depois que a saída se abrir.</color>",
  ui_story_5015_50150601_28_dialog_content = "Butler, você está realmente disposto a sacrificar esta cidade só para nos deixar partir?",
  ui_story_5015_50150601_29_dialog_content = "<color=#e8d9bb>A cidade não está mais... apta para viver... Não há esperança para este lugar...</color>",
  ui_story_5015_50150601_30_dialog_content = "<color=#e8d9bb>Lembrar...</color>",
  ui_story_5015_50150601_31_dialog_content = "<color=#e8d9bb>Abrir uma saída... é uma operação de alta autoridade.</color>",
  ui_story_5015_50150601_32_dialog_content = "<color=#e8d9bb>Vai... aumentar significativamente a carga nas estrelas da Alquimia.</color>",
  ui_story_5015_50150601_33_dialog_content = "<color=#e8d9bb>Pode até... desencadear explosões.</color>",
  ui_story_5015_50150601_34_dialog_content = "<color=#e8d9bb>Por favor, vá... a estas coordenadas e espere... para que você possa sair imediatamente quando for a hora.</color>",
  ui_story_5015_50150601_35_dialog_content = "Não! Quero que o Mordomo... vá embora conosco! *Soluço*",
  ui_story_5015_50150601_36_dialog_content = "Butler, você pode ir conosco, certo?",
  ui_story_5015_50150601_37_dialog_content = "<color=#e8d9bb>Desculpe, Gretel... Meu hub de dados está aqui. Não posso deixar.</color>",
  ui_story_5015_50150601_38_dialog_content = "<color=#e8d9bb>Eu preciso ficar... para abrir a saída para você.</color>",
  ui_story_5015_50150601_39_dialog_content = "Então eu vou ficar também...",
  ui_story_5015_50150601_40_dialog_content = "Gretel, me escute. Podemos voltar depois de sairmos.",
  ui_story_5015_50150601_41_dialog_content = "O mordomo não disse que abrir uma saída definitivamente provocaria a explosão.",
  ui_story_5015_50150601_42_dialog_content = "Vou guardar as coordenadas da cidade subterrânea para que a equipe de expedição Illumina possa encontrar este lugar e cavar a cidade subterrânea depois que partirmos.",
  ui_story_5015_50150601_43_dialog_content = "Você poderá se reunir com o Butler então. Não seria legal?",
  ui_story_5015_50150601_44_dialog_content = "Você não está mentindo para mim... certo?",
  ui_story_5015_50150601_45_dialog_content = "Eu prometo a você, vou incentivá-los a agir rapidamente depois que sairmos.",
  ui_story_5015_50150601_46_dialog_content = "*Sob* Butler... espere por nós em segurança aqui... até voltarmos.",
  ui_story_5015_50150601_47_dialog_content = "<color=#e8d9bb>Gretel, todo mundo, preparem-se agora... Preparem-se para sair.</color>",
  ui_story_5015_50150601_48_dialog_content = "Há mais alguma coisa que alguém precisa fazer primeiro?",
  ui_story_5015_50150601_49_dialog_content = "Vice, você armazenou os dados de pesquisa de Seamus?",
  ui_story_5015_50150601_50_dialog_content = "Você pode confiar em mim, Srta. Siobhan!",
  ui_story_5015_50150601_51_dialog_content = "Precisamos copiar mais alguns dados do hub de dados antes de sairmos?",
  ui_story_5015_50150601_52_dialog_content = "Você ainda quer fazer isso em um momento como este... Você não tem medo de criar mais problemas?",
  ui_story_5015_50150601_53_dialog_content = "Esqueça, Vice... Escapar é mais importante agora.",
  ui_story_5015_50150601_54_dialog_content = "O mais importante é garantir a segurança de todos... Gretel e Valência são a nossa maior descoberta desta expedição.",
  ui_story_5015_50150601_55_dialog_content = "Ufa... Finalmente posso voltar a vestir minhas roupas.",
  ui_story_5015_50150601_56_dialog_content = "É aqui que o Mordomo disse que é a saída?",
  ui_story_5015_50150601_57_dialog_content = "Correto.",
  ui_story_5015_50150601_58_dialog_content = "Mas PlayerName... Gretel parece bastante deprimida.",
  ui_story_5015_50150601_59_dialog_content = "Eu entendo como ela se sente.",
  ui_story_5015_50150601_60_dialog_content = "Para ela, o Mordomo é um amigo próximo, até mesmo um membro de sua família.",
  ui_story_5015_50150601_61_dialog_content = "Assim como eu e Soroz.",
  ui_story_5015_50150601_62_dialog_content = "Quero dizer... eles não têm outra escolha a não ser serem separados nesta situação.",
  ui_story_5015_50150601_63_dialog_content = "Hum...",
  ui_story_5015_50150601_64_dialog_content = "O que foi?",
  ui_story_5015_50150601_65_dialog_content = "Eu... de repente me sinto um pouco tonto...",
  ui_story_5015_50150601_66_dialog_content = "Pode ser... Ei, PlayerName...",
  ui_story_5015_50150601_67_dialog_content = "Ei! Acorde... O que há de errado com você... Ei...",
  ui_story_5015_50150601_68_dialog_content = "<color=#e8d9bb>Olá... PlayerName, você pode me ouvir?</color>",
  ui_story_5015_50150601_69_dialog_content = "Nós estabelecemos uma conexão telepática novamente?",
  ui_story_5015_50150601_70_dialog_content = "Como vão as coisas, Butler? A saída está aberta?",
  ui_story_5015_50150601_71_dialog_content = "Por que podemos de repente...",
  ui_story_5015_50150601_72_dialog_content = "<color=#e8d9bb>Eu obtive todas as autorizações desta cidade, então posso me conectar a você a qualquer momento.</color>",
  ui_story_5015_50150601_73_dialog_content = "Você não está abrindo a saída para nós...?",
  ui_story_5015_50150601_74_dialog_content = "<color=#e8d9bb>Já executei os procedimentos para abrir a saída, e ela ainda está carregando.</color>",
  ui_story_5015_50150601_75_dialog_content = "<color=#e8d9bb>Você poderá sair em 3 minutos.</color>",
  ui_story_5015_50150601_76_dialog_content = "... Honestamente falando, ainda estou surpreso que você concordou em abrir a saída para nós.",
  ui_story_5015_50150601_77_dialog_content = "Você continuou enfatizando que sua principal prioridade é manter a cidade segura e disse que não tinha emoções.",
  ui_story_5015_50150601_78_dialog_content = "Achei que você nos forçaria a ficar no subsolo para a segurança da cidade.",
  ui_story_5015_50150601_79_dialog_content = "<color=#e8d9bb>Eu protegi a cidade para manter nossa civilização viva.</color>",
  ui_story_5015_50150601_80_dialog_content = "<color=#e8d9bb>Já que todos os moradores se foram... Todo esse metal, concreto, poeira e até nós somos agora inúteis.</color>",
  ui_story_5015_50150601_81_dialog_content = "<color=#e8d9bb>De acordo com meus cálculos, mantê-lo aqui e fazer você enfrentar os terremotos, eclipses e fonte de energia instável...</color>",
  ui_story_5015_50150601_82_dialog_content = "<color=#e8d9bb>... não me ajuda a completar minha missão.</color>",
  ui_story_5015_50150601_83_dialog_content = "<color=#e8d9bb>Portanto, destruir a mim mesmo para mandá-lo embora está completamente de acordo com o meu programa.</color>",
  ui_story_5015_50150601_84_dialog_content = "<color=#e8d9bb>No final, é uma pena que não tenhamos conseguido proteger os moradores originais da cidade.</color>",
  ui_story_5015_50150601_85_dialog_content = "Não.",
  ui_story_5015_50150601_86_dialog_content = "Mesmo que os antigos moradores estejam agora perdidos na história...",
  ui_story_5015_50150601_87_dialog_content = "O espírito deles vive em você...",
  ui_story_5015_50150601_88_dialog_content = "Suas decisões e perseverança entregaram suas crenças.",
  ui_story_5015_50150601_89_dialog_content = "Você se conectou conosco depois de tanto tempo e transmitiu tudo para nós.",
  ui_story_5015_50150601_90_dialog_content = "Você não deve se arrepender.",
  ui_story_5015_50150601_91_dialog_content = "<color=#e8d9bb>Fico feliz que você reconheça tudo o que fiz.</color>",
  ui_story_5015_50150601_92_dialog_content = "<color=#e8d9bb>Mas ainda tenho alguns arrependimentos.</color>",
  ui_story_5015_50150601_93_dialog_content = "<color=#e8d9bb>Nós... finalmente recebemos uma nova residente, Gretel.</color>",
  ui_story_5015_50150601_94_dialog_content = "<color=#e8d9bb>Mas não posso acompanhar Gretel para sempre como ela quer.</color>",
  ui_story_5015_50150601_95_dialog_content = "<color=#e8d9bb>Eu quero que você transmita minhas desculpas a ela.</color>",
  ui_story_5015_50150601_96_dialog_content = "Para ser honesto, quando se trata desse tipo de coisa...",
  ui_story_5015_50150601_97_dialog_content = "Você está agindo... como um organismo vivo que pensa e tem emoções.",
  ui_story_5015_50150601_98_dialog_content = "Uma máquina não sentiria pena ou arrependimento, certo?",
  ui_story_5015_50150601_99_dialog_content = "<color=#e8d9bb>Talvez tenha sido assim que eu fui projetado em primeiro lugar.</color>",
  ui_story_5015_50150601_100_dialog_content = "<color=#e8d9bb>Meu design faz parecer que tenho um lado humano para facilitar a comunicação com você.</color>",
  ui_story_5015_50150601_101_dialog_content = "Mas neste momento, eu tenho um sentimento tão forte... que você tem sentimentos.",
  ui_story_5015_50150601_102_dialog_content = "Diga, como definimos se alguém ou algo \"tem sentimentos\"?",
  ui_story_5015_50150601_103_dialog_content = "<color=#e8d9bb>... Estrondo...</color>",
  ui_story_5015_50150601_104_dialog_content = "Que som é esse?",
  ui_story_5015_50150601_105_dialog_content = "<color=#e8d9bb>Desculpe, não posso responder à sua pergunta... A saída foi aberta e é hora de me despedir.</color>",
  ui_story_5015_50150601_106_dialog_content = "<color=#e8d9bb>Acho que não é apropriado terminar com um até logo, pois esta é realmente nossa última despedida.</color>",
  ui_story_5015_50150601_107_dialog_content = "<color=#e8d9bb>Desejo que todos vocês cheguem à superfície em segurança.</color>",
  ui_story_5015_50150601_108_dialog_content = "... Mordomo ...",
  ui_story_5015_50150601_109_dialog_content = "PlayerName, acorde agora! A saída está aberta!",
  ui_story_5015_50150601_110_dialog_content = "Você teve uma conexão com o Butler de novo?",
  ui_story_5015_50150601_111_dialog_content = "Sim... Ah certo, tenho algo a dizer a Gretel...",
  ui_story_5015_50150601_112_dialog_content = "*Sob* Irmã, eu-eu não quero ir embora.",
  ui_story_5015_50150601_113_dialog_content = "Eu quero voltar para o Butler...",
  ui_story_5015_50150601_114_dialog_content = "Gretel... Segure minha mão com força porque é hora de sair.",
  ui_story_5015_50150601_115_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5015_50150601_116_dialog_content = "É outro terremoto?",
  ui_story_5015_50150601_117_dialog_content = "Estamos sem tempo... PlayerName, Gretel, precisamos sair agora!",
  ui_story_5015_50150601_118_dialog_content = "Gretel, vamos!",
  ui_story_5015_50150601_119_dialog_content = "*Soluço* Mordomo...",
  ui_story_5015_50150601_120_dialog_content = "PlayerName, cuidado com os objetos caindo!",
  ui_story_5015_50150601_121_dialog_content = "... Ufa, isso foi por pouco. Cuidado com as pedras caindo!",
  ui_story_5015_50150601_122_dialog_content = "Conseguiremos chegar a tempo se subirmos assim?",
  ui_story_5015_50150601_123_dialog_content = "E se este lugar realmente explodir como o Mordomo disse?",
  ui_story_5015_50150601_124_dialog_content = "Eu realmente espero que Soroz possa nos pegar.",
  ui_story_5015_50150601_125_dialog_content = "Até um dirigível serviria... Só precisamos de algo que possa voar diretamente.",
  ui_story_5015_50150601_126_dialog_content = "Ruby, sua imaginação é tão irreal.",
  ui_story_5015_50150601_127_dialog_content = "Pelo menos o Colossus está por perto... Você sabe a que distância está um dirigível? Não é possível.",
  ui_story_5015_50150601_128_dialog_content = "Um dirigível?",
  ui_story_5015_50150601_129_dialog_content = "Princesa Carleen, você nunca viu um dirigível mesmo morando em Lumopolis?",
  ui_story_5015_50150601_130_dialog_content = "Não, de repente me lembrei que realmente temos algo que pode voar...",
  ui_story_5015_50150601_131_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5015_50150601_132_dialog_content = "Isso é... o som de uma explosão?",
  ui_story_5015_50150601_133_dialog_content = "Será que as estrelas da Alquimia já...",
  ui_story_5015_50150601_134_dialog_content = "Mordomo!!! *Soluço*",
  ui_story_5015_50150601_135_dialog_content = "Rápido! Suba e não solte! Gretel, eu vou te puxar para cima...",
  ui_story_5015_50150601_136_dialog_content = "Movam-se rapidamente, todos! Temos que deixar os níveis mais baixos! As explosões começaram.",
  ui_story_5015_50150601_137_dialog_content = "Ainda estamos a várias centenas de metros da superfície. Podemos não conseguir sair antes que as explosões nos alcancem...",
  ui_story_5015_50150601_138_dialog_content = "Cuidado com as pedras... O colapso está piorando!",
  ui_story_5015_50150601_139_dialog_content = "Isso não vai funcionar. Precisamos de uma maneira rápida de chegar à superfície!",
  ui_story_5015_50150601_140_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5015_50150601_141_dialog_content = "Oh não... a passagem rachou!",
  ui_story_5015_50150601_142_dialog_content = "E a rachadura é muito grande! Olha a cidade lá fora...",
  ui_story_5015_50150601_143_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5015_50150601_144_dialog_content = "Suba mais rápido!",
  ui_story_5015_50150601_145_dialog_content = "A superfície ainda está boa... Só precisamos subir até o elevador...",
  ui_story_5015_50150601_146_dialog_content = "Não... não podemos levantar. A parte do meio quebrou!",
  ui_story_5015_50150601_147_dialog_content = "<color=#e8d9bb>Buuuum!</color>",
  ui_story_5015_50150601_148_dialog_content = "Mesmo esta seção da passagem está desmoronando... Estamos condenados!",
  ui_story_5015_50150601_149_dialog_content = "Sai agora!!!",
  ui_story_5015_50150601_150_dialog_content = "Que? Isso é um... cavalo? Você pode convocar um cavalo com Luminatics?",
  ui_story_5015_50150601_151_dialog_content = "Todos, subam agora!",
  ui_story_5015_50150601_152_dialog_content = "PlayerName, Vice, pegue minha mão!",
  ui_story_5015_50150601_153_dialog_content = "Huff... estou chegando... subindo...",
  ui_story_5015_50150601_154_dialog_content = "Não, senhorita Siobhan, minhas calças estão prestes a quebrar...",
  ui_story_5015_50150601_155_dialog_content = "Mas estamos no ar. Estarei condenado se não me agarrar com força.",
  ui_story_5015_50150601_156_dialog_content = "Todos abaixo de mim também estarão condenados!",
  ui_story_5015_50150601_157_dialog_content = "Uau, você formou uma trilha tão longa!!!",
  ui_story_5015_50150601_158_dialog_content = "Eu não esperava que pudéssemos voar no ar assim...",
  ui_story_5015_50150601_159_dialog_content = "Carleen, podemos voltar para a passagem na superfície?",
  ui_story_5015_50150601_160_dialog_content = "Podemos! Os terremotos e explosões alargaram a saída...",
  ui_story_5015_50150601_161_dialog_content = "Podemos voar diretamente!",
  ui_story_5015_50150601_162_dialog_content = "Rouge, esta com certeza é uma experiência de vôo de 5 estrelas!",
  ui_story_5015_50150601_163_dialog_content = "É simplesmente muito emocionante!",
  ui_story_5015_50150601_164_dialog_content = "Você não pode diminuir as piadas agora? Você pode agir mais a sério?!",
  ui_story_5015_50150601_165_dialog_content = "Suspiro, quem teria esperado que iríamos embora assim...",
  ui_story_5015_50150601_166_dialog_content = "Assim, uma bela cidade tem...",
  ui_story_5015_50150601_167_dialog_content = "... Explodido em pedaços.",
  ui_story_5015_50150601_168_dialog_content = "Ufa! Graças a Deus saímos vivos.",
  ui_story_5015_50150601_169_dialog_content = "Vamos fazer uma contagem.",
  ui_story_5015_50150601_170_dialog_content = "Alguém se machucou?",
  ui_story_5015_50150601_171_dialog_content = "Todos se levantaram em segurança.",
  ui_story_5015_50150601_172_dialog_content = "Direito, PlayerName, eu, Vice, Valencia e Gretel precisamos reportar à Illumina...",
  ui_story_5015_50150601_173_dialog_content = "Por que eles devem segui-lo de volta para Illumina?",
  ui_story_5015_50150601_174_dialog_content = "Nimbus claramente os confiou à Igreja de Lumopolis.",
  ui_story_5015_50150601_175_dialog_content = "Isso se ninguém da Illumina estivesse lá.",
  ui_story_5015_50150601_176_dialog_content = "Siobhan, você é tão arrogante...",
  ui_story_5015_50150601_177_dialog_content = "Vocês caras! A melhor solução não é perguntar a Valencia e Gretel onde eles querem ir?",
  ui_story_5015_50150601_178_dialog_content = "Gretel...",
  ui_story_5015_50150601_179_dialog_content = "*Soluço* Irmã...",
  ui_story_5015_50150601_180_dialog_content = "Isso não é real... certo?",
  ui_story_5015_50150601_181_dialog_content = "Estou sonhando? Diga-me que isso é um pesadelo... *Sob*",
  ui_story_5015_50150601_182_dialog_content = "Acorde-me agora... Você pode pedir ao Mordomo para me acordar...",
  ui_story_5015_50150601_183_dialog_content = "Ainda preciso ir para a escola com o Anjo da Guarda nº 3... Dissemos que iríamos passear juntos...",
  ui_story_5015_50150601_184_dialog_content = "Nós íamos ver quem conseguia terminar uma volta ao redor do Central Park primeiro...",
  ui_story_5015_50150601_185_dialog_content = "O Mordomo me disse que encontrou uma nova receita que até você pode fazer facilmente, irmã...",
  ui_story_5015_50150601_186_dialog_content = "Fizemos um acordo para ir pescar, e ainda precisamos arrumar o quarto da mamãe e do papai como sempre...",
  ui_story_5015_50150601_187_dialog_content = "Está tão bagunçado lá agora... porque os dados estão em toda parte... Tenho certeza que eles ficarão felizes depois que limparmos.",
  ui_story_5015_50150601_188_dialog_content = "Gretel... a cidade já está...",
  ui_story_5015_50150601_189_dialog_content = "*Sob* Seria bom se isso fosse um pesadelo...",
  ui_story_5015_50150601_190_dialog_content = "Por que... Por que isso aconteceu...",
  ui_story_5015_50150601_191_dialog_content = "... O Mordomo... preparou uma nova receita?",
  ui_story_5015_50150601_192_dialog_content = "Sim... os ingredientes são os peixes que pegamos... e as plantas que encontramos da última vez...",
  ui_story_5015_50150601_193_dialog_content = "Isso deve ter sido difícil... Há apenas tantos ingredientes comestíveis... mas ele continuou pensando em maneiras de criar refeições diferentes para nós.",
  ui_story_5015_50150601_194_dialog_content = "Espero que possamos comer comida melhor aqui. . .",
  ui_story_5015_50150601_195_dialog_content = "Tenho certeza de que o mordomo ficará feliz em saber que você comerá na hora todos os dias e não será mais um comedor exigente...",
  ui_story_5015_50150601_196_dialog_content = "*Soluço* Eu... não serei mais um comedor exigente...",
  ui_story_5015_50150601_197_dialog_content = "Eu realmente quero que o Mordomo esteja aqui conosco...",
  ui_story_5015_50150601_198_dialog_content = "Seria ótimo se o Mordomo fosse uma pessoa... Então poderia ter ido embora com a gente...",
  ui_story_5015_50150601_199_dialog_content = "Seria capaz de ficar aqui conosco...",
  ui_story_5015_50150601_200_dialog_content = "Gretel, você ainda me tem. Eu sempre estarei aqui para você...",
  ui_story_5015_50150601_201_dialog_content = "Tadinha...",
  ui_story_5015_50150601_202_dialog_content = "Eu me pergunto... o que mamãe e papai pensariam se soubessem que voltamos ao mundo em que viviam.",
  ui_story_5015_50150601_203_dialog_content = "Conhecemos seus companheiros do passado e sobrevivemos juntos a uma crise.",
  ui_story_5015_50150601_204_dialog_content = "Eu protegi um ao outro. Finalmente reunimos coragem para vir a esta terra real.",
  ui_story_5015_50150601_205_dialog_content = "Podemos olhar para... o céu real.",
  ui_story_5015_50150601_206_dialog_content = "E as guerras? Ainda há guerras?",
  ui_story_5015_50150601_207_dialog_content = "Há também muitos Eclipsites aqui?",
  ui_story_5015_50150601_208_dialog_content = "Isso não importa porque ainda estaremos juntos, Gretel.",
  ui_story_5015_50150601_209_dialog_content = "Irmã...",
  ui_story_5015_50150601_210_dialog_content = "Vou encontrar um novo lar para nós. Confie em mim.",
  ui_story_5015_50150601_211_dialog_content = "Enquanto estivermos juntos, qualquer lugar pode ser nossa casa.",
  ui_story_5015_50150601_212_dialog_content = "... Enquanto eu estiver com minha irmã... então eu tenho um lar...",
  ui_story_5015_50150601_213_dialog_content = "(Parece que Gretel se acalmou...)",
  ui_story_5015_50150601_214_dialog_content = "(É possível que nem tudo tenha sido destruído... Ainda temos as coordenadas e informações, então a Illumina ainda pode escavá-lo.)",
  ui_story_5015_50150601_215_dialog_content = "(Mas não posso dizer isso diretamente agora.)",
  ui_story_5015_50150601_216_dialog_content = "(Ou então Gretel pode fazer algo impulsivo. Sem falar que Florine e os outros estão aqui...)",
  ui_story_5015_50150601_217_dialog_content = "O que você está pensando, senhorita Siobhan?",
  ui_story_5015_50150601_218_dialog_content = "Aham, nada. Vamos perguntar a Valencia e Gretel quais são seus planos para o futuro.",
  ui_story_5015_50150601_219_dialog_content = "Valencia, Gretel, você quer ir para Umbraton? Eu posso te mostrar o lugar.",
  ui_story_5015_50150601_220_dialog_content = "Talvez... ainda não me decidi, então posso te seguir por um tempo.",
  ui_story_5015_50150601_221_dialog_content = "Quero dizer, agora é a nossa vez de sermos estranhos...",
  ui_story_5015_50150601_222_dialog_content = "Certo, Ruby, temos algum dinheiro?",
  ui_story_5015_50150601_223_dialog_content = "Vamos precisar comprar algumas coisas para eles depois que chegarmos lá...",
  ui_story_5015_50150601_224_dialog_content = "Florine e eu podemos...",
  ui_story_5015_50150601_225_dialog_content = "Ah, nós também temos nossas próprias intenções... Você acha que precisamos nos preocupar com dinheiro? Veja!",
  ui_story_5015_50150601_226_dialog_content = "Eu... estou alucinando?",
  ui_story_5015_50150601_227_dialog_content = "Você pode parar de esfregar os olhos agora. Isso tudo é real.",
  ui_story_5015_50150601_228_dialog_content = "Eu peguei tudo isso enquanto estávamos saindo...",
  ui_story_5015_50150601_229_dialog_content = "Peças de droides, latas, componentes de ferramentas... e trajes antigos!",
  ui_story_5015_50150601_230_dialog_content = "Podemos vendê-los por muito dinheiro em Umbraton!",
  ui_story_5015_50150601_231_dialog_content = "Rouge, vamos ficar ricos!",
  ui_story_5015_50150601_232_dialog_content = "Ruby, como você pode dizer isso em um momento como este...",
  ui_story_5015_50150601_233_dialog_content = "Ahem, Valencia, Gretel, na verdade eu peguei tudo isso para você.",
  ui_story_5015_50150601_234_dialog_content = "Isso! Estes pertenciam a você. Você quer manter alguns deles como lembranças?",
  ui_story_5015_50150601_235_dialog_content = "O que Ruby quer dizer é que todas as coisas aqui são suas...",
  ui_story_5015_50150601_236_dialog_content = "... Pare de explicar... Você acha que eu não entendo?",
  ui_story_5015_50150601_237_dialog_content = "Vamos levar essas roupas. Você pode ficar com o resto...",
  ui_story_5015_50150601_238_dialog_content = "Ufa... Isso é ótimo! Você é bastante generoso!",
  ui_story_5015_50150601_239_dialog_content = "...",
  ui_story_5015_50150601_240_dialog_content = "Valencia, Gretel, você quer aceitar a sugestão de Rouge e ir para Umbraton?",
  ui_story_5015_50150601_241_dialog_content = "Gretel, o que você me diz? Onde você quer ir primeiro?",
  ui_story_5015_50150601_242_dialog_content = "Estou feliz enquanto estou com você, irmã...",
  ui_story_5015_50150601_243_dialog_content = "Ah certo, Gretel. Não consegui transmitir a mensagem do mordomo a você antes por causa do terremoto.",
  ui_story_5015_50150601_244_dialog_content = "Você quer ouvir agora?",
  ui_story_5015_50150601_245_dialog_content = "O-claro!",
  ui_story_5015_50150601_246_dialog_content = "O Mordomo disse que lamenta não poder continuar acompanhando você.",
  ui_story_5015_50150601_247_dialog_content = "E ele queria que eu lhe transmitisse suas desculpas.",
  ui_story_5015_50150601_248_dialog_content = "... OK eu entendi.",
  ui_story_5015_50150601_249_dialog_content = "Oh, Gretel, por que seus olhos estão vermelhos? tem areia...",
  ui_story_5015_50150601_250_dialog_content = "Ruby, deixe de lado as piadas sem graça agora.",
  ui_story_5015_50150601_251_dialog_content = "Ah... me desculpe.",
  ui_story_5015_50150601_252_dialog_content = "Valencia, Gretel, este é o meu comunicador... Esperem.",
  ui_story_5015_50150601_253_dialog_content = "Você não precisa me dar um. Eu tenho o comunicador do meu pai, então posso me comunicar com você.",
  ui_story_5015_50150601_254_dialog_content = "Eu sei, mas eu ainda quero que você pegue o meu. É mais seguro ter mais um.",
  ui_story_5015_50150601_255_dialog_content = "Além disso, se você tiver isso, poderá manter a relíquia de seu pai segura...",
  ui_story_5015_50150601_256_dialog_content = "Basta usar o comunicador que lhe dei se quiser entrar em contato com alguém no futuro.",
  ui_story_5015_50150601_257_dialog_content = "Além disso, quero trazer o diário de seu pai comigo de volta para Illumina. Você iria...",
  ui_story_5015_50150601_258_dialog_content = "Oh, sim, pode aceitar... Obrigado.",
  ui_story_5015_50150601_259_dialog_content = "...concordo com minha irmã...",
  ui_story_5015_50150601_260_dialog_content = "Ok, se você quiser voltar, é só me avisar.",
  ui_story_5015_50150601_261_dialog_content = "A Illumina sempre o receberá de braços abertos.",
  ui_story_5015_50150601_262_dialog_content = "O mesmo vale para a Igreja de Lumopolis.",
  ui_story_5015_50150601_263_dialog_content = "Pessoal, vocês precisam que eu te dê uma carona com o Colossus?",
  ui_story_5015_50150601_264_dialog_content = "Iremos primeiro para Lumopolis e Umbraton, depois para Illumina... Também podemos voar para o Deserto Rediesel.",
  ui_story_5015_50150601_265_dialog_content = "Excelente! Rouge, Valencia, Gretel, vamos fazer um tour PlayerName's Colossus agora!",
  ui_story_5015_50150601_266_dialog_content = "Colosso? É o Colosso do qual o Mordomo falou?",
  ui_story_5015_50150601_267_dialog_content = "Você quer saber? Apenas me siga!",
  ui_story_5015_50150601_268_dialog_content = "Senhorita Siobhan, vamos!",
  ui_story_5015_50150601_269_dialog_content = "Então eu vou pegar uma carona com você... Eu ainda quero conversar com Valencia e os outros ao longo do caminho.",
  ui_story_5015_50150601_270_dialog_content = "Florine, Erica, e vocês?",
  ui_story_5015_50150601_271_dialog_content = "Aceitamos de bom grado o seu convite, Princesa Carleen.",
  ui_story_5015_50150601_272_dialog_content = "Vamos então... Começaremos uma nova aventura com Valencia e Gretel.",
  ui_story_5015_50150601_273_dialog_content = "Recebi um conjunto de sinais misteriosos e acidentalmente descobri as ruínas antigas...",
  ui_story_5015_50150601_274_dialog_content = "... Após a verificação, o sinal misterioso foi enviado pelo pesquisador da Illumina desaparecido, Seamus, antes de sua morte...",
  ui_story_5015_50150601_275_dialog_content = "... As ruínas estão localizadas no subsolo. Parece uma cidade de refúgio civil...",
  ui_story_5015_50150601_276_dialog_content = "... As ruínas não têm mais moradores. O motivo do seu desaparecimento é desconhecido. Eu especulo que a razão para isso é uma invasão de Eclipsite...",
  ui_story_5015_50150601_277_dialog_content = "... Os filhos de Seamus, Valencia e Gretel, viviam sob os cuidados de uma inteligência artificial chamada Butler...",
  ui_story_5015_50150601_278_dialog_content = "... Eu obtive todos os dados de pesquisa deixados por Seamus. Isso será de grande valia para pesquisas futuras...",
  ui_story_5015_50150601_279_dialog_content = "... Como não havia tempo suficiente, não consegui obter informações sobre inteligência artificial...",
  ui_story_5015_50150601_280_dialog_content = "... Também não consegui salvar as estrelas da Alquimia, a fonte de energia que estava à beira da destruição...",
  ui_story_5015_50150601_281_dialog_content = "... Nós decidiremos se vamos escavar as ruínas depois de estudar os dados de Seamus...",
  ui_story_5015_50150601_282_dialog_content = "... Seamus serviu Illumina com todo o seu coração e alma ...",
  ui_story_5015_50150601_283_dialog_content = "... Mesmo em situação desesperadora, ele não desistiu de encontrar um caminho de sobrevivência para a geração futura...",
  ui_story_5015_50150601_284_dialog_content = "... Suas ações nas ruínas mostraram o nobre espírito dos Illumina. Ele é um exemplo para todos nós...",
  ui_story_5015_50150601_285_dialog_content = "... Isso é tudo para o meu relatório.",
  ui_story_5015_50150601_286_dialog_content = "... Esplendor Illumina!",
  ui_story_5015_50150601_287_dialog_content = "... Nimbus reconstruiu sua fé no Deus da Luz e refletiu profundamente...",
  ui_story_5015_50150601_288_dialog_content = "... Nos documentos escritos que deixou para trás, Nimbus confiou suas duas filhas à igreja...",
  ui_story_5015_50150601_289_dialog_content = "... Acho que, por bondade do Deus da Luz, a igreja deveria abrigar as duas meninas...",
  ui_story_5015_50150601_290_dialog_content = "... Muitas das inteligências artificiais nas ruínas já pararam de funcionar...",
  ui_story_5015_50150601_291_dialog_content = "... A inteligência artificial responsável pelo módulo biológico modificou muitos Eclipsites e foi nosso inimigo mais perigoso nas ruínas...",
  ui_story_5015_50150601_292_dialog_content = "... A admoestação do Deus da Luz foi comprovada...",
  ui_story_5015_50150601_293_dialog_content = "... A inteligência artificial das ruínas e a fonte de energia, as estrelas da Alquimia, foram destruídas pelas explosões...",
  ui_story_5015_50150601_294_dialog_content = "... Embora a pesquisadora da Illumina, Siobhan, tenha retirado os dados de pesquisa de Seamus...",
  ui_story_5015_50150601_295_dialog_content = "... Seamus nunca chegou perto do segredo mais sinistro no coração das ruínas...",
  ui_story_5015_50150601_296_dialog_content = "... Esta antiga ameaça agora foi enterrada sob a poeira e as rochas para sempre...",
  ui_story_5015_50150601_297_dialog_content = "... É tudo por agora.",
  ui_story_5015_50150601_298_dialog_content = "... Noite Branca lá no alto.",
  ui_story_5015_50150601_299_dialog_content = "Soroz, gostaria de saber se você pode me responder se ainda consegue me ouvir.",
  ui_story_5015_50150601_300_dialog_content = "É realmente impossível para a inteligência artificial desenvolver sentimentos?",
  ui_story_5015_50150601_301_dialog_content = "Recentemente conheci uma inteligência artificial que pode se comunicar comigo por meio de uma conexão telepática, assim como você.",
  ui_story_5015_50150601_302_dialog_content = "Era o guardião de uma antiga cidade subterrânea.",
  ui_story_5015_50150601_303_dialog_content = "No final, escolheu se sacrificar para nos deixar escapar, mas parecia não entender os sentimentos.",
  ui_story_5015_50150601_304_dialog_content = "Pensava que todas as suas ações eram predeterminadas por seu programa.",
  ui_story_5015_50150601_305_dialog_content = "Mas eu não acredito nisso.",
  ui_story_5015_50150601_306_dialog_content = "Todo aquele cuidado, confiança e conforto durante o tempo que passaram juntos... tudo isso por causa das configurações?",
  ui_story_5015_50150601_307_dialog_content = "Estava até disposto a se sacrificar para salvar os outros... Será que realmente fez isso para completar sua missão?",
  ui_story_5015_50150601_308_dialog_content = "Se esses não são exemplos de sentimentos, o que são sentimentos?",
  ui_story_5015_50150601_309_dialog_content = "Se eu negar tudo isso, então como eu estava vivendo antes de completar dezessete anos?",
  ui_story_5015_50150601_310_dialog_content = "... Tivemos muita sorte de poder escapar da Cidade Baixa com todos os nossos companheiros e aquelas duas irmãs.",
  ui_story_5015_50150601_311_dialog_content = "Além do Mordomo, devo também agradecer aos pais dessas duas irmãs.",
  ui_story_5015_50150601_312_dialog_content = "Não consigo imaginar o preço que pagaram para que suas filhas pudessem sobreviver...",
  ui_story_5015_50150601_313_dialog_content = "Soroz, com certeza meus pais também fizeram de tudo para que eu pudesse sobreviver, certo?",
  ui_story_5015_50150601_314_dialog_content = "...",
  ui_story_5015_50150601_315_dialog_content = "Quando poderei ouvir suas respostas novamente?"
}
return config
